private enum PythonRuntime {
    static var executableURL: URL {
        let manager = FileManager.default
        var candidates: [URL] = []

        if let configured = ProcessInfo.processInfo.environment["STICKERNEST_PYTHON"]?
            .trimmingCharacters(in: .whitespacesAndNewlines),
           !configured.isEmpty {
            candidates.append(URL(fileURLWithPath: configured))
        }

        let projectRoot = Bundle.main.bundleURL
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        candidates.append(projectRoot.appendingPathComponent(".venv/bin/python3"))
        candidates.append(URL(fileURLWithPath: "/opt/homebrew/bin/python3"))
        candidates.append(URL(fileURLWithPath: "/usr/local/bin/python3"))
        candidates.append(URL(fileURLWithPath: "/usr/bin/python3"))

        return candidates.first(where: { manager.isExecutableFile(atPath: $0.path) })
            ?? URL(fileURLWithPath: "/usr/bin/python3")
    }
}

enum AppInfo {
    static let version = "1.1.244"
    static let build = "20260607.005"
    static var displayVersion: String { "v\(version) (\(build))" }
}

@MainActor
final class AppDelegate: NSObject, NSApplicationDelegate {
    private var fallbackWindow: NSWindow?

    func applicationDidFinishLaunching(_ notification: Notification) {
        AppLogger.shared.log("app_delegate_did_finish_launching")
        NSApp.setActivationPolicy(.regular)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.7) {
            self.showMainWindowIfNeeded(allowFallbackCreate: false)
        }
    }

    func applicationShouldHandleReopen(_ sender: NSApplication, hasVisibleWindows flag: Bool) -> Bool {
        AppLogger.shared.log("app_delegate_reopen visibleWindows=\(flag)")
        showMainWindowIfNeeded(allowFallbackCreate: true)
        return true
    }

    private func showMainWindowIfNeeded(allowFallbackCreate: Bool) {
        let windowSummary = NSApp.windows.map { "\($0.title):visible=\($0.isVisible):mini=\($0.isMiniaturized)" }.joined(separator: "|")
        AppLogger.shared.log("app_delegate_show_window_check windows=\(NSApp.windows.count) details=\(windowSummary)")

        closeDuplicateMainWindows()

        if let window = NSApp.windows.first(where: { $0.title == "异形贴纸排版" && $0.isVisible && !$0.isMiniaturized }) {
            window.makeKeyAndOrderFront(nil)
            window.orderFrontRegardless()
            NSApp.activate(ignoringOtherApps: true)
            return
        }

        if let existing = NSApp.windows.first(where: { $0.title == "异形贴纸排版" }) {
            existing.makeKeyAndOrderFront(nil)
            existing.orderFrontRegardless()
            NSApp.activate(ignoringOtherApps: true)
            AppLogger.shared.log("app_delegate_show_window_existing visible=\(existing.isVisible)")
            return
        }

        if let existing = NSApp.windows.first(where: { !$0.isMiniaturized }) {
            existing.title = "异形贴纸排版"
            existing.makeKeyAndOrderFront(nil)
            existing.orderFrontRegardless()
            NSApp.activate(ignoringOtherApps: true)
            AppLogger.shared.log("app_delegate_show_window_existing_untitled")
            return
        }

        guard allowFallbackCreate else {
            AppLogger.shared.log("app_delegate_show_window_skip_create reason=launch_windowgroup_pending")
            return
        }

        let window = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: 1120, height: 720),
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered,
            defer: false
        )
        fallbackWindow = window
        window.isReleasedWhenClosed = false
        window.title = "异形贴纸排版"
        window.center()
        window.setFrameAutosaveName("StickerNestMacMainWindow")
        window.contentView = NSHostingView(
            rootView: ContentView()
                .environmentObject(NestViewModel.shared)
                .frame(minWidth: 1120, minHeight: 720)
        )
        window.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        AppLogger.shared.log("app_delegate_show_window_created")
    }

    private func closeDuplicateMainWindows() {
        let mainWindows = NSApp.windows.filter { $0.title == "异形贴纸排版" }
        guard let keep = mainWindows.first(where: { $0.isKeyWindow })
            ?? mainWindows.first(where: { $0.isVisible && !$0.isMiniaturized })
            ?? mainWindows.first
        else {
            return
        }
        guard mainWindows.count > 1 || NSApp.windows.contains(where: { !$0.isVisible && $0.title.isEmpty }) else { return }
        var closed = 0
        for window in mainWindows where window !== keep {
            window.close()
            closed += 1
        }
        for window in NSApp.windows where window !== keep && !window.isVisible && window.title.isEmpty {
            window.close()
            closed += 1
        }
        if let fallbackWindow, !fallbackWindow.isVisible {
            self.fallbackWindow = nil
        }
        AppLogger.shared.log("app_delegate_duplicate_windows_closed count=\(closed)")
    }
}

@main
struct StickerNestMacApp: App {
    @NSApplicationDelegateAdaptor(AppDelegate.self) private var appDelegate
    @StateObject private var model = NestViewModel.shared

    var body: some Scene {
        WindowGroup("异形贴纸排版") {
            ContentView()
                .environmentObject(model)
                .frame(minWidth: 1120, minHeight: 720)
        }
        .commands {
            CommandGroup(replacing: .newItem) {
                Button("导入图片...") { model.importImages() }
                    .keyboardShortcut("o", modifiers: .command)
                Button("智能排版") { model.adaptiveScaleNest() }
                    .keyboardShortcut("r", modifiers: .command)
                    .disabled(model.items.isEmpty || model.isWorking)
                Button("停止优化并保留结果") { model.stopOptimizationAndKeepCurrent() }
                    .keyboardShortcut(".", modifiers: .command)
                    .disabled(!model.isWorking)
                Button("导出 PNG...") { model.exportPNG() }
                    .keyboardShortcut("s", modifiers: .command)
                    .disabled(model.placements.isEmpty || model.isWorking)
                Button("导出 PSD 图层...") { model.exportPSD() }
                    .keyboardShortcut("s", modifiers: [.command, .shift])
                    .disabled(model.placements.isEmpty || model.isWorking)
            }
        }
    }
}

