    private var metrics: some View {
        VStack(alignment: .leading, spacing: 6) {
            metricRow("已放入", "\(model.placements.count) / \(model.items.count)")
            metricRow("整张占用", model.coverageText)
            metricRow("排版紧凑", model.compactnessText)
            metricRow("铺满高度", model.fillHeightText)
            metricRow("铺到高度", model.usedHeightText)
            Text(model.status)
                .font(.caption)
                .foregroundStyle(model.statusColor)
                .lineLimit(2)
        }
        .font(.callout)
        .padding(10)
        .background(Color(nsColor: .controlBackgroundColor))
        .clipShape(RoundedRectangle(cornerRadius: 8))
    }

    private func metricRow(_ title: String, _ value: String) -> some View {
        HStack {
            Text(title).foregroundStyle(.secondary)
            Spacer()
            Text(value).fontWeight(.semibold)
        }
    }

    private var previewPane: some View {
        VStack(spacing: 0) {
            HStack {
                Text("\(AppInfo.displayVersion)  \(model.status)")
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
                Spacer()
                if model.isWorking {
                    ProgressView()
                        .controlSize(.small)
                }
            }
            .padding(.horizontal, 18)
            .frame(height: 48)
            Divider()

            // v1.1.101: preview now fills the actual workspace.
            // Previously the image was capped at a hardcoded 820 px max dimension,
            // which left huge beige margins on big windows. We now use GeometryReader
            // to compute the real available space and scale the sheet to fit it
            // while preserving the sheet's aspect ratio.
            ZStack {
                Color(red: 0.94, green: 0.95, blue: 0.92)
                if let image = model.previewImage {
                    GeometryReader { geo in
                        let pad: CGFloat = 24
                        let availableW = max(1, geo.size.width - pad * 2)
                        let availableH = max(1, geo.size.height - pad * 2)
                        let sheetW = CGFloat(max(1, model.settings.sheetWidthPX))
                        let sheetH = CGFloat(max(1, model.settings.sheetHeightPX))
                        let fit = min(availableW / sheetW, availableH / sheetH)
                        let displayW = sheetW * fit
                        let displayH = sheetH * fit
                        Image(nsImage: image)
                            .resizable()
                            .interpolation(.high)
                            .frame(width: displayW, height: displayH)
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center)
                            .padding(pad)
                    }
                } else {
                    VStack(spacing: 12) {
                        Image(systemName: "square.stack.3d.down.right")
                            .font(.system(size: 54))
                            .foregroundStyle(.secondary)
                        Text("导入 25 张透明底图片后，点击开始智能排版。")
                            .font(.title3)
                        Text("排版按透明像素外形避让，不是矩形框排版。")
                            .foregroundStyle(.secondary)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .padding(80)
                }
            }
        }
    }
}

enum PaperPreset: String, CaseIterable, Identifiable {
    case template
    case a3
    case a4
    case custom

    var id: String { rawValue }

    // v1.1.104: user-facing label. rawValue stays "template" for log/cache stability,
    // but the UI shows the actual paper size so it's intuitive ("A2" is universally
    // understood, "模板" was unclear about which physical sheet).
    var displayName: String {
        switch self {
        case .template: return "A2"
        case .a3:       return "A3"
        case .a4:       return "A4"
        case .custom:   return "自定"
        }
    }

    var sizeMM: (width: Double, height: Double)? {
        switch self {
        case .template:
            return (419.95, 594.02)
        case .a3:
            return (297, 420)
        case .a4:
            return (210, 297)
        case .custom:
            return nil
        }
    }

    var defaultTargetLongSideMM: Double? {
        switch self {
        case .template:
            // v1.1.99: restored from 108.0 to keep the same A4-area-equivalent scaling as A3/A4.
            // A2 ≈ 4× A4 area, so longest side scales by √4 = 2.0 from A4 reference 56.65 → 113.3 mm.
            // The value had silently regressed to 108 between v1.1.84 and v1.1.90, leaving stickers
            // ~4.7% smaller (≈9.2% area loss) and capping alpha around 50% instead of the expected ~57%.
            // Template reserved regions (corner marks + QR) are already enforced in
            // templateReservedOccupancy(), so increasing longest side here does not risk overlapping them.
            return NestSettings.roundTargetLongSideMM(NestSettings.a4ReferenceTargetLongSideMM * sqrt((419.95 * 594.02) / NestSettings.a4ReferenceAreaMM2))
        case .a3:
            return NestSettings.roundTargetLongSideMM(NestSettings.a4ReferenceTargetLongSideMM * sqrt((297.0 * 420.0) / NestSettings.a4ReferenceAreaMM2))
        case .a4:
            return NestSettings.a4ReferenceTargetLongSideMM
        case .custom:
            return nil
        }
    }

    var defaultGapMM: Double? {
        switch self {
        case .template:
            return 6.0
        case .a3:
            return 4.2
        case .a4:
            return 3.0
        case .custom:
            return nil
        }
    }

    static func matching(widthMM: Double, heightMM: Double) -> PaperPreset {
        if matches(widthMM, heightMM, size: (419.95, 594.02)) { return .template }
        if matches(widthMM, heightMM, size: (297, 420)) { return .a3 }
        if matches(widthMM, heightMM, size: (210, 297)) { return .a4 }
        return .custom
    }

    private static func matches(_ width: Double, _ height: Double, size: (Double, Double)) -> Bool {
        let tolerance = 0.5
        let portrait = abs(width - size.0) <= tolerance && abs(height - size.1) <= tolerance
        let landscape = abs(width - size.1) <= tolerance && abs(height - size.0) <= tolerance
        return portrait || landscape
    }
}

struct NestSettings {
    static let a4ReferenceAreaMM2 = 210.0 * 297.0
    static let a4ReferenceTargetLongSideMM = 56.65
    static let edgeSafetyMarginMM = 4.0

    var sheetWidthMM = 419.95
    var sheetHeightMM = 594.02
    var dpi = 300
    var gapMM = 6.0
    var scalePercent = 100.0
    var targetLongSideMM = 113.3
    var angleStep = 15
    var materialSavingMode = false

    var pxPerMM: Double { Double(dpi) / 25.4 }
    // Actual pairwise gap the solver realizes. auto_nest.py works on a DOWN=20 grid
    // and dilates each piece by G = max(1, c(gapMM) // 2) cells, where
    // c(mm) = max(1, round(mm/25.4 * dpi / DOWN)); the nominal mm is therefore
    // coarsely quantized (e.g. 6mm -> ~6.8mm, 5mm -> ~3.4mm). Must stay in sync with
    // auto_nest.py's c()/G formula (guarded by test_gap_precision_policy.py).
    var effectiveGapMM: Double {
        let down = 20.0
        let c = max(1.0, (gapMM / 25.4 * Double(dpi) / down).rounded())
        let g = max(1.0, (c / 2.0).rounded(.down))
        return 2.0 * g * down / pxPerMM
    }
    var sheetWidthPX: Int { max(1, Int((sheetWidthMM * pxPerMM).rounded())) }
    var sheetHeightPX: Int { max(1, Int((sheetHeightMM * pxPerMM).rounded())) }
    var scale: Double { max(0.01, scalePercent / 100.0) }
    var sheetLinearScaleFromA4: Double {
        let area = max(1.0, sheetWidthMM * sheetHeightMM)
        return sqrt(area / Self.a4ReferenceAreaMM2)
    }

    func paperScaledLongSideMM(_ a4LongSideMM: Double) -> Double {
        Self.roundTargetLongSideMM(a4LongSideMM * sheetLinearScaleFromA4)
    }

    static func roundTargetLongSideMM(_ value: Double) -> Double {
        (value * 10).rounded() / 10
    }

    var isTemplateMaterial: Bool {
        dpi == 300 && abs(sheetWidthPX - 4960) <= 2 && abs(sheetHeightPX - 7016) <= 2
    }

    var logDescription: String {
        "sheetMM=\(sheetWidthMM)x\(sheetHeightMM) dpi=\(dpi) sheetPX=\(sheetWidthPX)x\(sheetHeightPX) gapMM=\(gapMM) gapMode=pair edgeSafetyMM=\(Self.edgeSafetyMarginMM) scalePercent=\(scalePercent) targetLongSideMM=\(targetLongSideMM) angleStep=\(angleStep) materialSavingMode=\(materialSavingMode)"
    }
}

struct StickerItem: Identifiable {
    let id = UUID()
    let name: String
    let image: CGImage
    let thumbnail: NSImage
    let originalWidth: Int
    let originalHeight: Int
    let width: Int
    let height: Int
    let alphaArea: Int
    let relativeScale: Double
    let shapeClass: ShapeClass
}

enum ShapeClass: String {
    case tall
    case wide
    case block
}

struct Variant {
    let image: CGImage
    let angle: Int
    let width: Int
    let height: Int
    let alphaPixels: Int
    let gridWidth: Int
    let gridHeight: Int
    let gapCells: Int
    let mask: [UInt8]
    let maskPoints: [GridPoint]
    let contourPoints: [GridPoint]
    let areaCells: Int
}

struct GridPoint {
    let x: Int
    let y: Int
}

struct GridRect {
    let x0: Int
    let y0: Int
    let x1: Int
    let y1: Int
}

struct WorkingSticker {
    let item: StickerItem
    let variants: [Variant]
    let preferredAngles: [Int]

    init(item: StickerItem, variants: [Variant], preferredAngles: [Int] = []) {
        self.item = item
        self.variants = variants
        self.preferredAngles = preferredAngles
    }
}

struct Placement: Identifiable {
    let id = UUID()
    let item: StickerItem
    let variant: Variant
    let gridX: Int
    let gridY: Int
}

struct AdaptiveScaleSnapshot: Codable {
    let appVersion: String
    let createdAt: String
    let targetCoverage: Double
    let achievedCoverage: Double
    let achievedAlphaCoverage: Double
    let achievedBboxCoverage: Double
    let achievedLayoutCoverage: Double
    let targetLongSideMM: Double
    let sheetWidthMM: Double?
    let sheetHeightMM: Double?
    let dpi: Int?
    let gapMM: Double?
    let scalePercent: Double?
    let angleStep: Int?
    let placedCount: Int
    let unplacedCount: Int
    let scales: [AdaptiveScaleRecord]
    let placements: [PlacementRecord]
}

struct AdaptiveScaleRecord: Codable {
    let name: String
    let relativeScale: Double
    let longSideMM: Double
    let sourceWidth: Int?
    let sourceHeight: Int?
    let sourceAlphaArea: Int?
}

struct PlacementRecord: Codable {
    let index: Int
    let name: String
    let angle: Int
    let relativeScale: Double
    let gridX: Int
    let gridY: Int
    let xPX: Int
    let yPX: Int
    let widthPX: Int
    let heightPX: Int
    let centerXPX: Double
    let centerYPX: Double
    let xMM: Double
    let yMM: Double
    let widthMM: Double
    let heightMM: Double
    let centerXMM: Double
    let centerYMM: Double
    let alphaPixels: Int
}

struct NestStats {
    let usedCells: Int
    let maxGridY: Int
    let gridWidth: Int
    let gridHeight: Int
    let cell: Int
    let whitespacePenalty: Int
}

