        "visual_audit score=\(score) verdict=\(verdict) grid=\(String(format: "%.1f%%", gridCoverage * 100)) alpha=\(String(format: "%.1f%%", alphaCoverage * 100)) largeBlank=\(String(format: "%.1f%%", largestSparseArea * 100)) centerBlank=\(String(format: "%.1f%%", centerBlank * 100)) lowerBlank=\(String(format: "%.1f%%", lowerBlank * 100)) rowImbalance=\(String(format: "%.2f", rowImbalance)) columnImbalance=\(String(format: "%.2f", columnImbalance)) sizeCV=\(String(format: "%.3f", sizeCV))"
    }
}

enum ManualLayoutTargets {
    static let gridCoverage = 0.64
    static let alphaCoverage = 0.54
    static let layoutBBoxCoverage = 0.95
    static let bboxCoverage = 0.94

    static func diagnosticText(for result: NestEngine.NestResult) -> String {
        let gridDelta = NestEngine.sheetCoverage(result) - gridCoverage
        let alphaDelta = NestEngine.alphaPixelCoverage(result) - alphaCoverage
        let layoutDelta = NestEngine.layoutBBoxCoverage(result) - layoutBBoxCoverage
        return "targetDiff grid=\(String(format: "%+.1f%%", gridDelta * 100)) alpha=\(String(format: "%+.1f%%", alphaDelta * 100)) layout=\(String(format: "%+.1f%%", layoutDelta * 100))"
    }
}

struct BatchShapeProfile {
    let count: Int
    let tallRatio: Double
    let wideRatio: Double
    let blockRatio: Double
    let medianAspect: Double
    let medianFill: Double
    let alphaSpread: Double
    let squareFillSpread: Double

    var seedUpperMM: Double {
        57.0
    }

    var fallbackSeedMM: Double {
        min(seedUpperMM, max(55.4, 56.20 - min(0.35, max(0, medianAspect - 1.70) * 0.12)))
    }

    var checkpointGridCoverage: Double {
        alphaSpread > 2.30 || medianAspect > 1.80 ? 0.685 : 0.695
    }

    var logDescription: String {
        "count=\(count) tall=\(String(format: "%.2f", tallRatio)) wide=\(String(format: "%.2f", wideRatio)) block=\(String(format: "%.2f", blockRatio)) medianAspect=\(String(format: "%.2f", medianAspect)) medianFill=\(String(format: "%.2f", medianFill)) alphaSpread=\(String(format: "%.2f", alphaSpread)) squareFillSpread=\(String(format: "%.2f", squareFillSpread)) seedUpperMM=\(String(format: "%.2f", seedUpperMM)) fallbackSeedMM=\(String(format: "%.2f", fallbackSeedMM)) checkpointGrid=\(String(format: "%.1f%%", checkpointGridCoverage * 100))"
    }

    static func analyze(_ items: [StickerItem]) -> BatchShapeProfile {
        guard !items.isEmpty else {
            return BatchShapeProfile(count: 0, tallRatio: 0, wideRatio: 0, blockRatio: 0, medianAspect: 1, medianFill: 0, alphaSpread: 1, squareFillSpread: 1)
        }
        let count = Double(items.count)
        let tall = Double(items.filter { $0.shapeClass == .tall }.count) / count
        let wide = Double(items.filter { $0.shapeClass == .wide }.count) / count
        let block = max(0, 1 - tall - wide)
        let aspects = items.map { Double(max($0.width, $0.height)) / Double(max(1, min($0.width, $0.height))) }
        let fills = items.map { Double($0.alphaArea) / Double(max(1, $0.width * $0.height)) }
        let alphaAreas = items.map { Double(max(1, $0.alphaArea)) }.sorted()
        let squareFills = items.map { Double($0.alphaArea) / pow(Double(max(1, max($0.width, $0.height))), 2.0) }.sorted()
        let alphaSpread = percentile(alphaAreas, 0.90) / max(1, percentile(alphaAreas, 0.10))
        let squareFillSpread = percentile(squareFills, 0.90) / max(0.0001, percentile(squareFills, 0.10))
        return BatchShapeProfile(
            count: items.count,
            tallRatio: tall,
            wideRatio: wide,
            blockRatio: block,
            medianAspect: median(aspects),
            medianFill: median(fills),
            alphaSpread: alphaSpread,
            squareFillSpread: squareFillSpread
        )
    }

    private static func median(_ values: [Double]) -> Double {
        let sorted = values.sorted()
        guard !sorted.isEmpty else { return 0 }
        let mid = sorted.count / 2
        if sorted.count.isMultiple(of: 2) {
            return (sorted[mid - 1] + sorted[mid]) / 2.0
        }
        return sorted[mid]
    }

    private static func percentile(_ sortedValues: [Double], _ quantile: Double) -> Double {
        guard !sortedValues.isEmpty else { return 0 }
        let clamped = min(1, max(0, quantile))
        let index = Int((Double(sortedValues.count - 1) * clamped).rounded())
        return sortedValues[index]
    }
}

struct BatchStrategyRoute {
    let label: String
    let earlyFastPathOrder: [(target: Double, strategy: Int)]
    let fastPathOrder: [(target: Double, strategy: Int)]
    let quickTargets: [Double]
    let quickStrategies: [Int]
    let checkpointGridCoverage: Double
    let stopAfterFirstSolvedCandidate: Bool

    var logDescription: String {
        let early = earlyFastPathOrder.map { "\(String(format: "%.0f", $0.target * 100)):\($0.strategy)" }.joined(separator: ",")
        let fast = fastPathOrder.map { "\(String(format: "%.0f", $0.target * 100)):\($0.strategy)" }.joined(separator: ",")
        return "label=\(label) early=\(early) fast=\(fast) quickTargets=\(quickTargets.map { String(format: "%.0f", $0 * 100) }.joined(separator: ",")) quickStrategies=\(quickStrategies.map(String.init).joined(separator: ",")) checkpointGrid=\(String(format: "%.1f%%", checkpointGridCoverage * 100)) routeStop=\(stopAfterFirstSolvedCandidate ? "on" : "off")"
    }

    static func resolve(profile: BatchShapeProfile, baselineCoverage: Double, exactManual: Bool) -> BatchStrategyRoute {
        let baseOrder: [(target: Double, strategy: Int)] = [
            (0.82, 1),
            (0.80, 3),
            (0.80, 0),
            (0.78, 2),
            (0.78, 1),
            (0.78, 0)
        ]
        let recoveryFirst: [(target: Double, strategy: Int)] = [
            (0.78, 2),
            (0.82, 1),
            (0.80, 3),
            (0.80, 0),
            (0.78, 1),
            (0.78, 0)
        ]
        let denseTallPairFirst: [(target: Double, strategy: Int)] = [
            (0.78, 1),
            (0.78, 2),
            (0.82, 1),
            (0.80, 3),
            (0.80, 0),
            (0.78, 0)
        ]
        let tallFirst: [(target: Double, strategy: Int)] = [
            (0.78, 2),
            (0.80, 3),
            (0.80, 0),
            (0.78, 1),
            (0.78, 0),
            (0.82, 1)
        ]

        if !exactManual,
           baselineCoverage >= 0.70,
           profile.tallRatio >= 0.55,
           profile.medianFill >= 0.70 {
            return BatchStrategyRoute(
                label: "dense_tall_pair_first",
                earlyFastPathOrder: denseTallPairFirst,
                fastPathOrder: denseTallPairFirst,
                quickTargets: [0.78, 0.80, 0.82],
                quickStrategies: [1, 2, 0, 3],
                checkpointGridCoverage: max(profile.checkpointGridCoverage, 0.695),
                stopAfterFirstSolvedCandidate: false
            )
        }

        if exactManual || baselineCoverage >= 0.68 {
            return BatchStrategyRoute(
                label: exactManual ? "exact_manual_recovery_first" : "dense_recovery_first",
                earlyFastPathOrder: recoveryFirst,
                fastPathOrder: recoveryFirst,
                quickTargets: [0.78, 0.80, 0.82],
                quickStrategies: [2, 1, 0, 3],
                checkpointGridCoverage: max(profile.checkpointGridCoverage, 0.695),
                stopAfterFirstSolvedCandidate: false
            )
        }

        if profile.tallRatio >= 0.62 {
            return BatchStrategyRoute(
                label: "tall_portrait_safe_fill",
                earlyFastPathOrder: tallFirst,
                fastPathOrder: tallFirst,
                quickTargets: [0.78, 0.80, 0.82],
                quickStrategies: [2, 1, 0, 3],
                checkpointGridCoverage: profile.checkpointGridCoverage,
                stopAfterFirstSolvedCandidate: true
            )
        }

        if profile.blockRatio >= 0.42 || profile.medianFill >= 0.66 {
            return BatchStrategyRoute(
                label: "block_dense_area",
                earlyFastPathOrder: recoveryFirst,
                fastPathOrder: recoveryFirst,
                quickTargets: [0.80, 0.82, 0.78],
                quickStrategies: [1, 2, 0, 3],
                checkpointGridCoverage: max(profile.checkpointGridCoverage, 0.700),
                stopAfterFirstSolvedCandidate: false
            )
        }

        return BatchStrategyRoute(
            label: "balanced_default",
            earlyFastPathOrder: baseOrder,
            fastPathOrder: baseOrder,
            quickTargets: [0.78, 0.80, 0.82],
            quickStrategies: [0, 1, 2, 3],
            checkpointGridCoverage: profile.checkpointGridCoverage,
            stopAfterFirstSolvedCandidate: false
        )
    }
}

final class MetalNestAccelerator: @unchecked Sendable {
    static let shared = MetalNestAccelerator()

    private let device: MTLDevice?
    private let commandQueue: MTLCommandQueue?
    private let pipeline: MTLComputePipelineState?
    private let fitMapPipeline: MTLComputePipelineState?
    private let lock = NSLock()

    private init() {
        guard let device = MTLCreateSystemDefaultDevice() else {
            self.device = nil
            self.commandQueue = nil
            self.pipeline = nil
            self.fitMapPipeline = nil
            AppLogger.shared.log("metal_unavailable no_default_device")
            return
        }
        var resolvedQueue: MTLCommandQueue?
        var resolvedPipeline: MTLComputePipelineState?
        var resolvedFitMapPipeline: MTLComputePipelineState?
        do {
            let library = try device.makeLibrary(source: Self.kernelSource, options: nil)
            guard let function = library.makeFunction(name: "scoreCandidates"),
                  let fitMapFunction = library.makeFunction(name: "fitMapScoreCandidates") else {
                self.device = device
                self.commandQueue = nil
                self.pipeline = nil
                self.fitMapPipeline = nil
                AppLogger.shared.log("metal_unavailable missing_kernel")
                return
            }
            resolvedQueue = device.makeCommandQueue()
            resolvedPipeline = try device.makeComputePipelineState(function: function)
            resolvedFitMapPipeline = try device.makeComputePipelineState(function: fitMapFunction)
            self.device = device
            self.commandQueue = resolvedQueue
            self.pipeline = resolvedPipeline
            self.fitMapPipeline = resolvedFitMapPipeline
            AppLogger.shared.log("metal_ready device=\(device.name)")
        } catch {
            self.device = device
            self.commandQueue = nil
            self.pipeline = nil
            self.fitMapPipeline = nil
            AppLogger.shared.log("metal_unavailable error=\(error.localizedDescription)")
        }
    }

    func bestCandidate(
        occupied: [UInt8],
        sheetW: Int,
        sheetH: Int,
        variant: Variant,
        currentMaxY: Int,
        scanY: Int
    ) -> (x: Int, y: Int, score: Int)? {
        guard let device, let commandQueue, let pipeline else { return nil }
        let limitX = sheetW - variant.gridWidth
        let limitY = min(sheetH - variant.gridHeight, scanY)
        guard limitX >= 0, limitY >= 0, !variant.maskPoints.isEmpty else { return nil }

        let xSteps = limitX / 2 + 1
        let ySteps = limitY + 1
        let candidateCount = xSteps * ySteps
        guard candidateCount > 0 else { return nil }

        var pointData = [Int32]()
        pointData.reserveCapacity(variant.maskPoints.count * 2)
        for point in variant.maskPoints {
            pointData.append(Int32(point.x))
            pointData.append(Int32(point.y))
        }

        var constants: [Int32] = [
            Int32(sheetW),
            Int32(sheetH),
            Int32(variant.gridWidth),
            Int32(variant.gridHeight),
            Int32(currentMaxY),
            Int32(xSteps),
            Int32(variant.maskPoints.count),
            Int32(max(1, variant.maskPoints.count / 900)),
            Int32(max(1, variant.maskPoints.count / 700)),
            Int32(max(1, variant.maskPoints.count / 800)),
        ]
        var scores = Array(repeating: Int32.max, count: candidateCount)

        guard let occupiedBuffer = device.makeBuffer(bytes: occupied, length: occupied.count, options: .storageModeShared),
              let pointBuffer = device.makeBuffer(bytes: pointData, length: pointData.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let constantBuffer = device.makeBuffer(bytes: &constants, length: constants.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let scoreBuffer = device.makeBuffer(bytes: &scores, length: scores.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let commandBuffer = commandQueue.makeCommandBuffer(),
              let encoder = commandBuffer.makeComputeCommandEncoder()
        else { return nil }

        lock.lock()
        encoder.setComputePipelineState(pipeline)
        encoder.setBuffer(occupiedBuffer, offset: 0, index: 0)
        encoder.setBuffer(pointBuffer, offset: 0, index: 1)
        encoder.setBuffer(constantBuffer, offset: 0, index: 2)
        encoder.setBuffer(scoreBuffer, offset: 0, index: 3)

        let threads = MTLSize(width: candidateCount, height: 1, depth: 1)
        let groupWidth = min(pipeline.maxTotalThreadsPerThreadgroup, 256)
        let groups = MTLSize(width: groupWidth, height: 1, depth: 1)
        encoder.dispatchThreads(threads, threadsPerThreadgroup: groups)
        encoder.endEncoding()
        commandBuffer.commit()
        commandBuffer.waitUntilCompleted()
        lock.unlock()

        let pointer = scoreBuffer.contents().bindMemory(to: Int32.self, capacity: candidateCount)
        var bestScore = Int32.max
        var bestIndex = -1
        for index in 0..<candidateCount where pointer[index] < bestScore {
            bestScore = pointer[index]
            bestIndex = index
        }
        guard bestIndex >= 0, bestScore < Int32.max else { return nil }
        let y = bestIndex / xSteps
        let x = (bestIndex % xSteps) * 2
        return (x, y, Int(bestScore))
    }

    func bestFitMapCandidate(
        occupied: [UInt8],
        sheetW: Int,
        sheetH: Int,
        variant: Variant,
        currentMaxY: Int,
        scanY: Int,
        xStep: Int,
        placedCount: Int
    ) -> (x: Int, y: Int, score: Int)? {
        guard let device, let commandQueue, let fitMapPipeline else { return nil }
        let limitX = sheetW - variant.gridWidth
        let limitY = min(sheetH - variant.gridHeight, scanY)
        let resolvedXStep = max(1, xStep)
        guard limitX >= 0, limitY >= 0, !variant.maskPoints.isEmpty else { return nil }

        let xSteps = limitX / resolvedXStep + 1
        let ySteps = limitY + 1
        let candidateCount = xSteps * ySteps
        guard candidateCount > 0 else { return nil }

        var pointData = [Int32]()
