        ]
        var scores = Array(repeating: Int32.max, count: candidateCount)

        guard let occupiedBuffer = device.makeBuffer(bytes: occupied, length: occupied.count, options: .storageModeShared),
              let pointBuffer = device.makeBuffer(bytes: pointData, length: pointData.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let constantBuffer = device.makeBuffer(bytes: &constants, length: constants.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let scoreBuffer = device.makeBuffer(bytes: &scores, length: scores.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let commandBuffer = commandQueue.makeCommandBuffer(),
              let encoder = commandBuffer.makeComputeCommandEncoder()
        else { return nil }

        lock.lock()
        encoder.setComputePipelineState(fitMapPipeline)
        encoder.setBuffer(occupiedBuffer, offset: 0, index: 0)
        encoder.setBuffer(pointBuffer, offset: 0, index: 1)
        encoder.setBuffer(constantBuffer, offset: 0, index: 2)
        encoder.setBuffer(scoreBuffer, offset: 0, index: 3)

        let threads = MTLSize(width: candidateCount, height: 1, depth: 1)
        let groupWidth = min(fitMapPipeline.maxTotalThreadsPerThreadgroup, 256)
        let groups = MTLSize(width: groupWidth, height: 1, depth: 1)
        encoder.dispatchThreads(threads, threadsPerThreadgroup: groups)
        encoder.endEncoding()
        commandBuffer.commit()
        commandBuffer.waitUntilCompleted()
        lock.unlock()

        let pointer = scoreBuffer.contents().bindMemory(to: Int32.self, capacity: candidateCount)
        var bestScore = Int32.max
        var bestIndex = -1
        for index in 0..<candidateCount where pointer[index] < bestScore {
            bestScore = pointer[index]
            bestIndex = index
        }
        guard bestIndex >= 0, bestScore < Int32.max else { return nil }
        let y = bestIndex / xSteps
        let x = (bestIndex % xSteps) * resolvedXStep
        return (x, y, Int(bestScore))
    }

    func topFitMapCandidates(
        occupied: [UInt8],
        sheetW: Int,
        sheetH: Int,
        variant: Variant,
        currentMaxY: Int,
        scanY: Int,
        xStep: Int,
        placedCount: Int,
        limit: Int
    ) -> [(x: Int, y: Int, score: Int)] {
        guard let device, let commandQueue, let fitMapPipeline else { return [] }
        let limitX = sheetW - variant.gridWidth
        let limitY = min(sheetH - variant.gridHeight, scanY)
        let resolvedXStep = max(1, xStep)
        let resolvedLimit = max(1, limit)
        guard limitX >= 0, limitY >= 0, !variant.maskPoints.isEmpty else { return [] }

        let xSteps = limitX / resolvedXStep + 1
        let ySteps = limitY + 1
        let candidateCount = xSteps * ySteps
        guard candidateCount > 0 else { return [] }

        var pointData = [Int32]()
        pointData.reserveCapacity(variant.maskPoints.count * 2)
        for point in variant.maskPoints {
            pointData.append(Int32(point.x))
            pointData.append(Int32(point.y))
        }

        var constants: [Int32] = [
            Int32(sheetW),
            Int32(sheetH),
            Int32(variant.gridWidth),
            Int32(variant.gridHeight),
            Int32(currentMaxY),
            Int32(xSteps),
            Int32(variant.maskPoints.count),
            Int32(max(1, variant.maskPoints.count / 900)),
            Int32(resolvedXStep),
            Int32(placedCount),
        ]
        var scores = Array(repeating: Int32.max, count: candidateCount)

        guard let occupiedBuffer = device.makeBuffer(bytes: occupied, length: occupied.count, options: .storageModeShared),
              let pointBuffer = device.makeBuffer(bytes: pointData, length: pointData.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let constantBuffer = device.makeBuffer(bytes: &constants, length: constants.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let scoreBuffer = device.makeBuffer(bytes: &scores, length: scores.count * MemoryLayout<Int32>.stride, options: .storageModeShared),
              let commandBuffer = commandQueue.makeCommandBuffer(),
              let encoder = commandBuffer.makeComputeCommandEncoder()
        else { return [] }

        lock.lock()
        encoder.setComputePipelineState(fitMapPipeline)
        encoder.setBuffer(occupiedBuffer, offset: 0, index: 0)
        encoder.setBuffer(pointBuffer, offset: 0, index: 1)
        encoder.setBuffer(constantBuffer, offset: 0, index: 2)
        encoder.setBuffer(scoreBuffer, offset: 0, index: 3)

        let threads = MTLSize(width: candidateCount, height: 1, depth: 1)
        let groupWidth = min(fitMapPipeline.maxTotalThreadsPerThreadgroup, 256)
        let groups = MTLSize(width: groupWidth, height: 1, depth: 1)
        encoder.dispatchThreads(threads, threadsPerThreadgroup: groups)
        encoder.endEncoding()
        commandBuffer.commit()
        commandBuffer.waitUntilCompleted()
        lock.unlock()

        let pointer = scoreBuffer.contents().bindMemory(to: Int32.self, capacity: candidateCount)
        var best: [(index: Int, score: Int32)] = []
        best.reserveCapacity(resolvedLimit)
        for index in 0..<candidateCount {
            let score = pointer[index]
            guard score < Int32.max else { continue }
            if best.count < resolvedLimit {
                best.append((index, score))
                best.sort { $0.score < $1.score }
            } else if let last = best.last, score < last.score {
                best[best.count - 1] = (index, score)
                best.sort { $0.score < $1.score }
            }
        }
        return best.map { entry in
            let y = entry.index / xSteps
            let x = (entry.index % xSteps) * resolvedXStep
            return (x, y, Int(entry.score))
        }
    }

    private static let kernelSource = """
    #include <metal_stdlib>
    using namespace metal;

    kernel void scoreCandidates(
        device const uchar *occupied [[buffer(0)]],
        device const int *points [[buffer(1)]],
        device const int *c [[buffer(2)]],
        device int *scores [[buffer(3)]],
        uint gid [[thread_position_in_grid]]
    ) {
        int sheetW = c[0];
        int sheetH = c[1];
        int gridW = c[2];
        int gridH = c[3];
        int currentMaxY = c[4];
        int xSteps = c[5];
        int pointCount = c[6];
        int contactStep = c[7];
        int emptyStep = c[8];
        int supportStep = c[9];
        int y = int(gid) / xSteps;
        int x = (int(gid) - y * xSteps) * 2;

        for (int i = 0; i < pointCount; i++) {
            int px = x + points[i * 2];
            int py = y + points[i * 2 + 1];
            if (occupied[py * sheetW + px] != 0) {
                scores[gid] = 2147483647;
                return;
            }
        }

        int contact = 0;
        for (int i = 0; i < pointCount; i += contactStep) {
            int px = x + points[i * 2];
            int py = y + points[i * 2 + 1];
            if (px == 0 || py == 0 || px == sheetW - 1 || py == sheetH - 1) {
                contact += 1;
            } else {
                contact += occupied[py * sheetW + px - 1] != 0 ? 2 : 0;
                contact += occupied[py * sheetW + px + 1] != 0 ? 2 : 0;
                contact += occupied[(py - 1) * sheetW + px] != 0 ? 2 : 0;
                contact += occupied[(py + 1) * sheetW + px] != 0 ? 2 : 0;
                contact += occupied[(py - 1) * sheetW + px - 1] != 0 ? 1 : 0;
                contact += occupied[(py - 1) * sheetW + px + 1] != 0 ? 1 : 0;
                contact += occupied[(py + 1) * sheetW + px - 1] != 0 ? 1 : 0;
                contact += occupied[(py + 1) * sheetW + px + 1] != 0 ? 1 : 0;
            }
        }

        int cavity = 0;
        for (int i = 0; i < pointCount; i += emptyStep) {
            int px = x + points[i * 2];
            int py = y + points[i * 2 + 1] + 1;
            if (py < sheetH && occupied[py * sheetW + px] == 0) {
                cavity += 1;
            }
        }

        int support = 0;
        for (int i = 0; i < pointCount; i += supportStep) {
            int px = x + points[i * 2];
            int py = y + points[i * 2 + 1];
            if (py == 0 || px == 0 || px == sheetW - 1) {
                support -= 1;
            } else {
                int distance = 1;
                while (distance <= 8) {
                    int yy = py + distance;
                    if (yy >= sheetH || occupied[yy * sheetW + px] != 0) {
                        break;
                    }
                    distance += 1;
                }
                support += min(distance, 8);
            }
        }
        support = max(support, 0);

        int heightAfter = max(currentMaxY, y + gridH);
        int centerPenalty = abs((x + gridW / 2) - sheetW / 2);
        int sidePenalty = min(x, max(0, sheetW - x - gridW));
        scores[gid] = heightAfter * 900000 + y * 2200 + sidePenalty * 25 + centerPenalty * 10 + cavity * 260 + support * 1400 - contact * 3200;
    }

    kernel void fitMapScoreCandidates(
        device const uchar *occupied [[buffer(0)]],
        device const int *points [[buffer(1)]],
        device const int *c [[buffer(2)]],
        device int *scores [[buffer(3)]],
        uint gid [[thread_position_in_grid]]
    ) {
        int sheetW = c[0];
        int sheetH = c[1];
        int gridW = c[2];
        int gridH = c[3];
        int currentMaxY = c[4];
        int xSteps = c[5];
        int pointCount = c[6];
        int contactStep = c[7];
        int xStep = c[8];
        int placedCount = c[9];
        int y = int(gid) / xSteps;
        int x = (int(gid) - y * xSteps) * xStep;

        for (int i = 0; i < pointCount; i++) {
            int px = x + points[i * 2];
            int py = y + points[i * 2 + 1];
            if (occupied[py * sheetW + px] != 0) {
                scores[gid] = 2147483647;
                return;
            }
        }

        int contact = 0;
        for (int i = 0; i < pointCount; i += contactStep) {
            int px = x + points[i * 2];
            int py = y + points[i * 2 + 1];
            if (px == 0 || py == 0 || px == sheetW - 1 || py == sheetH - 1) {
                contact += 2;
            } else {
                contact += occupied[py * sheetW + px - 1] != 0 ? 2 : 0;
                contact += occupied[py * sheetW + px + 1] != 0 ? 2 : 0;
                contact += occupied[(py - 1) * sheetW + px] != 0 ? 2 : 0;
                contact += occupied[(py + 1) * sheetW + px] != 0 ? 2 : 0;
                contact += occupied[(py - 1) * sheetW + px - 1] != 0 ? 1 : 0;
                contact += occupied[(py - 1) * sheetW + px + 1] != 0 ? 1 : 0;
                contact += occupied[(py + 1) * sheetW + px - 1] != 0 ? 1 : 0;
                contact += occupied[(py + 1) * sheetW + px + 1] != 0 ? 1 : 0;
            }
        }

        int heightAfter = max(currentMaxY, y + gridH);
        int edgeSlack = min(x, max(0, sheetW - x - gridW)) + min(y, max(0, sheetH - y - gridH));
        int centerPenalty = abs((x + gridW / 2) - sheetW / 2) + abs((y + gridH / 2) - sheetH / 2);
        int bottomBias = placedCount > 16 ? abs((y + gridH) - sheetH) * 4 : 0;
        scores[gid] = heightAfter * 1800 + y * 10 + edgeSlack * 18 + centerPenalty * 3 + bottomBias - contact * 1450;
    }
    """
}

