    nonisolated private static func externalProcessRSSMB(pid: Int32) -> Double? {
        let psProcess = Process()
        psProcess.executableURL = URL(fileURLWithPath: "/bin/ps")
        psProcess.arguments = ["-o", "rss=", "-p", "\(pid)"]
        let outputPipe = Pipe()
        psProcess.standardOutput = outputPipe
        psProcess.standardError = Pipe()
        do {
            try psProcess.run()
            psProcess.waitUntilExit()
        } catch {
            return nil
        }
        guard psProcess.terminationStatus == 0 else { return nil }
        let output = String(data: outputPipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        guard let rssKB = Double(output.trimmingCharacters(in: .whitespacesAndNewlines)) else { return nil }
        return rssKB / 1024.0
    }

    /// Terminate an external solver reliably: SIGTERM first, then SIGKILL if it is
    /// still alive after a short grace period. `Process.terminate()` only sends
    /// SIGTERM, which a child stuck inside a long numpy/BLAS C call may not handle
    /// until the call returns; a plain `waitUntilExit()` would then block the
    /// monitor while a runaway solver keeps growing. Escalating to SIGKILL bounds
    /// that worst case.
    nonisolated private static func hardTerminate(_ process: Process, graceSeconds: Double = 2.0) {
        guard process.isRunning else {
            process.waitUntilExit()
            return
        }
        process.terminate() // SIGTERM
        let deadline = Date().addingTimeInterval(graceSeconds)
        while process.isRunning, Date() < deadline {
            Thread.sleep(forTimeInterval: 0.05)
        }
        if process.isRunning {
            kill(process.processIdentifier, SIGKILL)
            AppLogger.shared.log("external_auto_nest_process_sigkill_escalated pid=\(process.processIdentifier) graceSeconds=\(String(format: "%.1f", graceSeconds))")
        }
        process.waitUntilExit()
    }

