    private static func highDensityTargetLongSide(for items: [StickerItem], settings: NestSettings, capA4: Double? = 57.0) -> Double {
        let targetA4 = ManualTargetProfile.load()?.solverTargetLongSideMM
            ?? ManualLayoutProfile.load()?.targetLongSideMM(forItemCount: items.count)
            ?? NestSettings.a4ReferenceTargetLongSideMM
        // v1.1.105: RESTORED the spaciousTemplateCapA4 = 54.0 override that v1.1.104
        // removed. The removal triggered a runaway behavior on template+6mm gap+25 items
        // where the solver could not find a feasible 25/25 at 113.3 mm under the edge
        // reserves and kept allocating candidate state until memory hit 165 GB and
        // crashed the user's Mac.
        // The cap is restored as a hard safety stop. Future improvement direction:
        // proper a-priori feasibility check + wall-clock timeout, not removing the cap.
        let spaciousTemplateCapA4: Double? = settings.isTemplateMaterial && settings.gapMM >= 5.5 ? 54.0 : nil
        let effectiveCapA4: Double?
        if let capA4, let spaciousTemplateCapA4 {
            effectiveCapA4 = min(capA4, spaciousTemplateCapA4)
        } else {
            effectiveCapA4 = capA4 ?? spaciousTemplateCapA4
        }
        let cappedA4 = effectiveCapA4.map { min(targetA4, $0) } ?? targetA4
        return settings.paperScaledLongSideMM(cappedA4)
    }

    private static func applyHighDensityTargetSeed(to settings: inout NestSettings, items: [StickerItem], capA4: Double? = 57.0) {
        guard items.count >= 25 else { return }
        settings.targetLongSideMM = highDensityTargetLongSide(for: items, settings: settings, capA4: capA4)
        settings.angleStep = 15
    }

    init() {
        AppLogger.shared.log("app_start version=\(AppInfo.displayVersion)")
        _ = MetalNestAccelerator.shared
        refreshLearningSummary()
        if let autoImportPath = ProcessInfo.processInfo.environment["STICKERNEST_AUTO_IMPORT"] {
            AppLogger.shared.log("auto_import_scheduled path=\(autoImportPath)")
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                self.importImagesWithFallback(fromFolder: URL(fileURLWithPath: autoImportPath), autoRefine: true)
            }
        } else {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
                self.restoreLastImportIfPossible()
            }
        }
    }

    var previewDisplaySize: CGSize {
        let w = CGFloat(settings.sheetWidthPX)
        let h = CGFloat(settings.sheetHeightPX)
        let scale = min(1.0, 820 / max(w, h))
        return CGSize(width: max(1, w * scale), height: max(1, h * scale))
    }

    var coverageText: String {
        guard let stats else { return "0%" }
        let total = max(1, stats.gridWidth * stats.gridHeight)
        let value = Double(stats.usedCells) / Double(total) * 100
        return String(format: "%.1f%%", value)
    }

    var compactnessText: String {
        guard let stats else { return "0%" }
        let total = max(1, stats.gridWidth * max(1, stats.maxGridY))
        let value = Double(stats.usedCells) / Double(total) * 100
        return String(format: "%.1f%%", value)
    }

    var usedHeightText: String {
        guard let stats else { return "0 mm" }
        let mm = Double(stats.maxGridY * stats.cell) / settings.pxPerMM
        return String(format: "%.1f mm", mm)
    }

    var fillHeightText: String {
        guard let stats else { return "0%" }
        let value = Double(stats.maxGridY) / Double(max(1, stats.gridHeight)) * 100
        return String(format: "%.1f%%", value)
    }

    func applyPaperPreset(_ preset: PaperPreset) {
        guard let size = preset.sizeMM else { return }
        settings.sheetWidthMM = size.width
        settings.sheetHeightMM = size.height
        if let targetLongSideMM = preset.defaultTargetLongSideMM {
            settings.targetLongSideMM = targetLongSideMM
        }
        if let gapMM = preset.defaultGapMM {
            settings.gapMM = gapMM
        }
        placements = []
        stats = nil
        previewImage = renderPreview(drawGuides: false)
        status = "已切换材料为 \(preset.displayName)：\(Int(size.width)) x \(Int(size.height)) mm，最长边 \(String(format: "%.1f", settings.targetLongSideMM)) mm，间距 \(String(format: "%.1f", settings.gapMM)) mm"
        AppLogger.shared.log("paper_preset_selected preset=\(preset.rawValue.uppercased()) sheetMM=\(size.width)x\(size.height) targetLongSideMM=\(String(format: "%.2f", settings.targetLongSideMM)) gapMM=\(String(format: "%.2f", settings.gapMM))")
    }

    func importImages() {
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = true
        panel.canChooseDirectories = true
        panel.allowedContentTypes = [.png, .tiff, .webP, .image]
        panel.message = "选择已经扣好透明底的贴纸图片，或直接选择图片文件夹"
        if panel.runModal() != .OK { return }

        if panel.urls.count == 1, isDirectory(panel.urls[0]) {
            SecurityBookmarkStore.save(folder: panel.urls[0], fileNames: nil)
            _ = importImages(fromFolder: panel.urls[0], autoRefine: false)
            return
        }

        _ = importImages(fromFileURLs: panel.urls, statusText: "已导入", remember: true)
    }

    @discardableResult
    private func importImages(fromFileURLs urls: [URL], statusText: String, remember: Bool) -> Int {
        status = "正在读取图片"
        statusColor = .secondary
        let imageURLs = urls
            .filter { ["png", "tif", "tiff", "webp", "jpg", "jpeg"].contains($0.pathExtension.lowercased()) }
        AppLogger.shared.log("import_files_begin selected=\(imageURLs.count) remember=\(remember) settings=\(settings.logDescription)")
        if let folder = imageURLs.first?.deletingLastPathComponent() {
            SecurityBookmarkStore.save(folder: folder, fileNames: imageURLs.map(\.lastPathComponent))
        }
        if remember {
            SecurityBookmarkStore.saveFiles(imageURLs)
        }
        var loaded: [StickerItem] = []
        for url in imageURLs {
            let access = SecurityBookmarkStore.accessFile(url)
            if let item = loadSticker(url: access.url) {
                loaded.append(item)
            } else {
                AppLogger.shared.log("import_failed file=\(url.path)")
            }
            access.stop()
        }
        items = applyLearnedSizeVariation(loaded)
        placements = []
        stats = nil
        previewImage = renderPreview(drawGuides: false)
        status = "\(statusText) \(items.count) 张，点击自动排版"
        AppLogger.shared.log("import_files_end loaded=\(items.count)")
        return items.count
    }

    func restoreLastImportIfPossible() {
        guard items.isEmpty, !isWorking else { return }
        if let folder = SecurityBookmarkStore.resolvedFolder(), FileManager.default.fileExists(atPath: folder.path) {
            AppLogger.shared.log("restore_last_import_begin folder=\(folder.path)")
            let loaded = importImages(fromFolder: folder, autoRefine: false)
            if loaded > 0 {
                status = "已自动恢复上次导入 \(loaded) 张"
                AppLogger.shared.log("restore_last_import_end source=folder loaded=\(loaded)")
                return
            }
            AppLogger.shared.log("restore_last_import_folder_empty path=\(folder.path)")
        } else if let folder = SecurityBookmarkStore.resolvedFolder() {
            AppLogger.shared.log("restore_last_import_skipped reason=folder_missing path=\(folder.path)")
        }

        let fileURLs = SecurityBookmarkStore.resolvedFileURLs()
        guard !fileURLs.isEmpty else {
            AppLogger.shared.log("restore_last_import_end loaded=0 reason=no_saved_file_bookmarks")
            return
        }
        AppLogger.shared.log("restore_last_import_files_begin files=\(fileURLs.count)")
        let loaded = importImages(fromFileURLs: fileURLs, statusText: "已自动恢复上次导入", remember: false)
        if loaded > 0 {
            status = "已自动恢复上次导入 \(loaded) 张"
            AppLogger.shared.log("restore_last_import_end source=files loaded=\(loaded)")
        } else {
            AppLogger.shared.log("restore_last_import_end loaded=0")
        }
    }

    func importImagesWithFallback(fromFolder folder: URL, autoRefine: Bool) {
        let loaded = importImages(fromFolder: folder, autoRefine: autoRefine)
        guard loaded == 0,
              let saved = SecurityBookmarkStore.resolvedFolder(),
              saved.path != folder.path
        else { return }
        AppLogger.shared.log("auto_import_retry_saved_folder path=\(saved.path)")
        _ = importImages(fromFolder: saved, autoRefine: autoRefine)
    }

    @discardableResult
    func importImages(fromFolder folder: URL, autoRefine: Bool) -> Int {
        status = "正在读取测试图片"
        statusColor = .secondary
        let access = SecurityBookmarkStore.access(folder)
        defer { access.stop() }
        let readableFolder = access.url
        let urls = (try? FileManager.default.contentsOfDirectory(
            at: readableFolder,
            includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles]
        )) ?? []
        let preferredNames = SecurityBookmarkStore.selectedFileNames(for: readableFolder)
        var imageURLs = urls
            .filter { ["png", "tif", "tiff", "webp", "jpg", "jpeg"].contains($0.pathExtension.lowercased()) }
            .sorted { lhs, rhs in
                lhs.lastPathComponent.localizedStandardCompare(rhs.lastPathComponent) == .orderedAscending
            }
        if let preferredNames, !preferredNames.isEmpty {
            let preferred = Set(preferredNames)
            imageURLs = imageURLs.filter { preferred.contains($0.lastPathComponent) }
        } else if imageURLs.count > 25 {
            AppLogger.shared.log("auto_import_limit_to_25 folder=\(readableFolder.path) found=\(imageURLs.count)")
            imageURLs = Array(imageURLs.prefix(25))
        }
        AppLogger.shared.log("auto_import_begin folder=\(readableFolder.path) selected=\(imageURLs.count) rememberedSelection=\(preferredNames?.count ?? 0) settings=\(settings.logDescription)")
        var loaded: [StickerItem] = []
        for url in imageURLs {
            if let item = loadSticker(url: url) {
                loaded.append(item)
            } else {
                AppLogger.shared.log("auto_import_failed file=\(url.path)")
            }
        }
        items = applyLearnedSizeVariation(loaded)
        placements = []
        stats = nil
        previewImage = renderPreview(drawGuides: false)
        status = "已导入测试图片 \(items.count) 张"
        AppLogger.shared.log("auto_import_end loaded=\(items.count)")
        if items.count > 0 {
            SecurityBookmarkStore.save(folder: readableFolder, fileNames: imageURLs.map(\.lastPathComponent))
            SecurityBookmarkStore.saveFiles(imageURLs)
        }
        if autoRefine, !items.isEmpty {
            let optimizer = ProcessInfo.processInfo.environment["STICKERNEST_AUTO_OPTIMIZER"]
            if optimizer == "fitmapv2" {
                fitMapV2Nest()
            } else if optimizer == "v2" {
                globalV2Nest()
            } else if optimizer == "adaptive" {
                adaptiveScaleNest()
            } else if optimizer == "quick" {
                runNest(compact: false)
            } else {
                refineCurrentLayout()
            }
        }
        return items.count
    }

    private func isDirectory(_ url: URL) -> Bool {
        (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) == true
    }

    func stopOptimizationAndKeepCurrent() {
        guard isWorking else { return }
        activeOptimizationTask?.cancel()
        activeOptimizationTask = nil
        optimizationRunID += 1
        isWorking = false

        if !placements.isEmpty {
            previewImage = renderPreview(drawGuides: true)
            saveLatestPreview()
            let resultStats: NestStats
            if let stats {
                resultStats = stats
            } else {
                let cell = NestEngine.cellSize(for: settings)
                let gridW = max(1, settings.sheetWidthPX / cell)
                let gridH = max(1, settings.sheetHeightPX / cell)
                let usedCells = placements.reduce(0) { $0 + $1.variant.areaCells }
                let maxY = placements.reduce(0) { max($0, $1.gridY + $1.variant.gridHeight) }
                resultStats = NestStats(usedCells: usedCells, maxGridY: maxY, gridWidth: gridW, gridHeight: gridH, cell: cell, whitespacePenalty: 0)
            }
            let result: NestEngine.NestResult = (placements, resultStats, [], [])
            status = "已停止，保留当前最好结果，可导出：\(NestEngine.coverageDiagnosticText(for: result))"
            statusColor = .secondary
            AppLogger.shared.log("optimization_stop_keep_current placed=\(placements.count) \(NestEngine.coverageDiagnosticText(for: result))")
        } else {
            status = "已停止，还没有可导出的排版结果"
            statusColor = .orange
            AppLogger.shared.log("optimization_stop_keep_current placed=0")
        }
    }

    func runNest(compact: Bool) {
        guard !items.isEmpty else { return }
        isWorking = true
        status = compact ? "正在尝试更省料的排法" : "正在自动异形排版"
        statusColor = .secondary

        let currentItems = items
        let currentSettings = settings
        AppLogger.shared.log("nest_begin compact=\(compact) items=\(currentItems.count) settings=\(currentSettings.logDescription)")
        Task.detached(priority: .userInitiated) {
            let started = Date()
            let result = NestEngine.nest(items: currentItems, settings: currentSettings, rounds: compact ? 6 : 2)
            let elapsed = Date().timeIntervalSince(started)
            AppLogger.shared.log("nest_end placed=\(result.placements.count) unplaced=\(result.unplaced.count) usedCells=\(result.stats.usedCells) maxGridY=\(result.stats.maxGridY) elapsed=\(String(format: "%.3f", elapsed))s")
            for line in result.debugLines {
                AppLogger.shared.log(line)
            }
            await MainActor.run {
                self.placements = result.placements
                self.stats = result.stats
                self.previewImage = self.renderPreview(drawGuides: true)
                self.status = result.unplaced.isEmpty ? "排版完成，可以导出" : "\(result.unplaced.count) 张放不下，请增大材料或缩小图片"
                self.statusColor = result.unplaced.isEmpty ? .secondary : .orange
                self.autoExportPSDIfRequested()
                self.isWorking = false
            }
        }
    }

