    func learnedNest() {
        guard !items.isEmpty else { return }
        isWorking = true
        status = "正在按人工样本排版"
        statusColor = .secondary

        let currentItems = items
        var preparedSettings = settings
        let profile = ManualLayoutProfile.load()
        if currentItems.count >= 25 {
            Self.applyHighDensityTargetSeed(to: &preparedSettings, items: currentItems, capA4: 57.0)
        } else if let target = profile?.targetLongSideMM(forItemCount: currentItems.count) {
            preparedSettings.targetLongSideMM = target
            preparedSettings.angleStep = 15
        } else {
            preparedSettings.targetLongSideMM = max(54, settings.targetLongSideMM)
            preparedSettings.angleStep = 15
        }
        let learnedSettings = preparedSettings
        settings = learnedSettings

        AppLogger.shared.log("learned_nest_begin items=\(currentItems.count) profileLoaded=\(profile != nil) settings=\(learnedSettings.logDescription)")
        Task.detached(priority: .userInitiated) {
            let started = Date()
            var result = NestEngine.visualNest(items: currentItems, settings: learnedSettings, rounds: 2)
            let greedyResult = NestEngine.nest(items: currentItems, settings: learnedSettings, rounds: 6)
            if NestEngine.isResult(greedyResult, betterThan: result) {
                result = greedyResult
            }
            var finalSettings = learnedSettings
            let recovered = NestEngine.ensureAllPlaced(items: currentItems, startSettings: learnedSettings, current: result, logPrefix: "learned_nest")
            result = recovered.result
            finalSettings = recovered.settings
            if result.unplaced.isEmpty {
                let boosted = NestEngine.visualDensityBoost(items: currentItems, baseSettings: finalSettings, current: result, upperLongSideMM: min(profile?.targetLongSideMM(forItemCount: currentItems.count) ?? finalSettings.targetLongSideMM * 1.04, finalSettings.targetLongSideMM + 1.2))
                result = boosted.result
                finalSettings = boosted.settings
            }
            let elapsed = Date().timeIntervalSince(started)
            AppLogger.shared.log("learned_nest_end targetLongSideMM=\(String(format: "%.2f", finalSettings.targetLongSideMM)) placed=\(result.placements.count) unplaced=\(result.unplaced.count) elapsed=\(String(format: "%.3f", elapsed))s")
            for line in result.debugLines {
                AppLogger.shared.log(line)
            }
            let finalResult = result
            let resolvedSettings = finalSettings
            await MainActor.run {
                self.settings = resolvedSettings
                self.placements = finalResult.placements
                self.stats = finalResult.stats
                self.previewImage = self.renderPreview(drawGuides: true)
                self.status = finalResult.unplaced.isEmpty ? "已按人工样本校准，最长边 \(String(format: "%.1f", resolvedSettings.targetLongSideMM)) mm" : "\(finalResult.unplaced.count) 张放不下，需要继续降低尺寸"
                self.statusColor = finalResult.unplaced.isEmpty ? .secondary : .orange
                self.autoExportPSDIfRequested()
                self.isWorking = false
            }
        }
    }

