    func adaptiveScaleNest() {
        guard !items.isEmpty else { return }
        activeOptimizationTask?.cancel()
        optimizationRunID += 1
        let runID = optimizationRunID
        isWorking = true
        status = "正在单张缩放优化：目标 78% / 80% / 82%"
        statusColor = .secondary

        let currentItems = items
        var preparedSettings = settings
        let externalAutoNestEnabled = currentItems.count >= 20
            && ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_AUTO_NEST"] != "0"
        if currentItems.count >= 25 {
            if externalAutoNestEnabled {
                preparedSettings.angleStep = 15
                if preparedSettings.isTemplateMaterial,
                   preparedSettings.gapMM >= 5.5,
                   let templateTarget = PaperPreset.template.defaultTargetLongSideMM,
                   preparedSettings.targetLongSideMM < templateTarget - 0.05 {
                    AppLogger.shared.log("adaptive_scale_external_target_restore old=\(String(format: "%.2f", preparedSettings.targetLongSideMM)) new=\(String(format: "%.2f", templateTarget)) reason=external_auto_nest_uses_visual_balance")
                    preparedSettings.targetLongSideMM = templateTarget
                }
            } else {
                Self.applyHighDensityTargetSeed(to: &preparedSettings, items: currentItems, capA4: 57.0)
            }
        } else {
            preparedSettings.angleStep = 15
        }
        let currentSettings = preparedSettings
        settings = currentSettings
        AppLogger.shared.log("adaptive_scale_ui_begin items=\(currentItems.count) settings=\(currentSettings.logDescription)")

        activeOptimizationTask = Task.detached(priority: .userInitiated) {
            let started = Date()
            if ProcessInfo.processInfo.environment["STICKERNEST_DISABLE_CACHE"] != "1" {
                let snapshotURL = AppPaths.supportDirectory.appendingPathComponent("adaptive-scales.json")
                var cacheReason = ""
                if let data = try? Data(contentsOf: snapshotURL),
                   let snapshot = try? JSONDecoder().decode(AdaptiveScaleSnapshot.self, from: data),
                   snapshot.targetLongSideMM > 0 {
                    var cachedSettings = currentSettings
                    cachedSettings.targetLongSideMM = snapshot.targetLongSideMM
                    if let cached = NestEngine.rebuildAdaptiveScaleSnapshot(snapshot, items: currentItems, settings: cachedSettings, missReason: &cacheReason) {
                    let elapsed = Date().timeIntervalSince(started)
                    let best = cached.result
                    let finalCachedSettings = cachedSettings
                    let finalScaledItems = cached.scaledItems
                    let finalTargetCoverage = cached.targetCoverage
                    let cacheNotice = cacheReason.hasPrefix("legacy_") ? NestViewModel.cacheStatusText(for: cacheReason) : "已复用上次成功排版"
                    let visualAudit = NestEngine.visualAuditSummary(for: best)
                    let finalStatus = "\(cacheNotice)：\(NestEngine.coverageDiagnosticText(for: best))；\(visualAudit)，用时 \(String(format: "%.2f", elapsed)) 秒"
                    AppLogger.shared.log("adaptive_scale_cache_status_ui text=\(finalStatus)")
                    AppLogger.shared.log("adaptive_scale_ui_end_cached targetCoverage=\(String(format: "%.1f%%", cached.targetCoverage * 100)) placed=\(best.placements.count) unplaced=\(best.unplaced.count) \(NestEngine.coverageDiagnosticText(for: best)) \(ManualLayoutTargets.diagnosticText(for: best)) compactness=\(NestEngine.coverageText(for: best)) heightReach=\(NestEngine.heightReachText(for: best)) whitespacePenalty=\(best.stats.whitespacePenalty) elapsed=\(String(format: "%.3f", elapsed))s")
                    AppLogger.shared.log(NestEngine.visualAuditLogLine(for: best))
                    for line in best.debugLines {
                        AppLogger.shared.log(line)
                    }
                    await MainActor.run {
                        guard runID == self.optimizationRunID else { return }
                        self.settings = finalCachedSettings
                        self.placements = best.placements
                        self.stats = best.stats
                        self.previewImage = self.renderPreview(drawGuides: true)
                        self.saveLatestPreview()
                        self.saveAdaptiveScaleSnapshot(items: finalScaledItems, settings: finalCachedSettings, result: best, targetCoverage: finalTargetCoverage)
                        self.status = finalStatus
                        self.statusColor = .secondary
                        self.autoExportPSDIfRequested()
                        self.activeOptimizationTask = nil
                        self.isWorking = false
                    }
                    return
                    }
                    let missStatus = NestViewModel.cacheStatusText(for: cacheReason.isEmpty ? "cache_unavailable" : cacheReason)
                    AppLogger.shared.log("adaptive_scale_cache_status_ui text=\(missStatus)")
                    await MainActor.run {
                        guard runID == self.optimizationRunID else { return }
                        self.status = missStatus
                        self.statusColor = .orange
                    }
                } else {
                    AppLogger.shared.log("adaptive_scale_cache_unavailable action=full_solve")
                    let missStatus = NestViewModel.cacheStatusText(for: "cache_unavailable")
                    AppLogger.shared.log("adaptive_scale_cache_status_ui text=\(missStatus)")
                    await MainActor.run {
                        guard runID == self.optimizationRunID else { return }
                        self.status = missStatus
                        self.statusColor = .secondary
                    }
                }
            } else {
                AppLogger.shared.log("adaptive_scale_cache_disabled action=full_solve")
                let missStatus = NestViewModel.cacheStatusText(for: "cache_disabled")
                AppLogger.shared.log("adaptive_scale_cache_status_ui text=\(missStatus)")
                await MainActor.run {
                    guard runID == self.optimizationRunID else { return }
                    self.status = missStatus
                    self.statusColor = .secondary
                }
            }
            if Task.isCancelled {
                AppLogger.shared.log("adaptive_scale_ui_cancelled before_full_solve")
                return
            }

            if externalAutoNestEnabled {
                await MainActor.run {
                    guard runID == self.optimizationRunID else { return }
                    self.status = "正在运行高密度套料器"
                    self.statusColor = .secondary
                }
                if let external = Self.runExternalAutoNest(items: currentItems, settings: currentSettings),
                   external.result.unplaced.isEmpty,
                   external.result.placements.count == currentItems.count {
                    let elapsed = Date().timeIntervalSince(started)
                    let best = external.result
                    let finalExternalSettings = external.settings
                    let visualAudit = NestEngine.visualAuditSummary(for: best)
                    AppLogger.shared.log("adaptive_scale_external_auto_nest_used placed=\(best.placements.count) unplaced=\(best.unplaced.count) \(NestEngine.coverageDiagnosticText(for: best)) \(ManualLayoutTargets.diagnosticText(for: best)) compactness=\(NestEngine.coverageText(for: best)) heightReach=\(NestEngine.heightReachText(for: best)) whitespacePenalty=\(best.stats.whitespacePenalty) elapsed=\(String(format: "%.3f", elapsed))s")
                    AppLogger.shared.log(NestEngine.visualAuditLogLine(for: best))
                    for line in best.debugLines {
                        AppLogger.shared.log(line)
                    }
                    await MainActor.run {
                        guard runID == self.optimizationRunID else { return }
                        self.settings = finalExternalSettings
                        self.placements = best.placements
                        self.stats = best.stats
                        self.previewImage = self.renderPreview(drawGuides: true)
                        self.saveLatestPreview()
                        self.saveAdaptiveScaleSnapshot(items: external.scaledItems, settings: finalExternalSettings, result: best, targetCoverage: external.targetCoverage)
                        self.status = "高密度套料完成：\(NestEngine.coverageDiagnosticText(for: best))；\(visualAudit)"
                        self.statusColor = .secondary
                        self.autoExportPSDIfRequested()
                        self.activeOptimizationTask = nil
                        self.isWorking = false
                    }
                    return
                }
                let allowLegacySwiftFallback = ProcessInfo.processInfo.environment["STICKERNEST_ALLOW_SWIFT_FALLBACK_AFTER_EXTERNAL"] == "1"
                if !allowLegacySwiftFallback {
                    let elapsed = Date().timeIntervalSince(started)
                    let safetyStatus = "安全停止：高密度计算失败或内存异常，已避免进入高内存旧求解器"
                    AppLogger.shared.log("adaptive_scale_external_auto_nest_blocked_legacy_fallback reason=collision_guard_memory_safety elapsed=\(String(format: "%.3f", elapsed))s")
                    await MainActor.run {
                        guard runID == self.optimizationRunID else { return }
                        self.status = safetyStatus
                        self.statusColor = .orange
                        self.activeOptimizationTask = nil
                        self.isWorking = false
                    }
                    return
                }
                AppLogger.shared.log("adaptive_scale_external_auto_nest_fallback action=swift_solver override=STICKERNEST_ALLOW_SWIFT_FALLBACK_AFTER_EXTERNAL")
            }
            if Task.isCancelled {
                AppLogger.shared.log("adaptive_scale_ui_cancelled after_external_auto_nest")
                return
            }

            let optimized = await NestEngine.adaptiveScaleOptimize(
                items: currentItems,
                baseSettings: currentSettings
            ) { result, settings, message in
                await self.showOptimizationProgress(result: result, settings: settings, message: message, runID: runID)
            }
            if Task.isCancelled {
                AppLogger.shared.log("adaptive_scale_ui_cancelled after_full_solve")
                return
            }
            let elapsed = Date().timeIntervalSince(started)
            let best = optimized.result
            let finalSettings = optimized.settings
            let visualAudit = NestEngine.visualAuditSummary(for: best)
            AppLogger.shared.log("adaptive_scale_ui_end targetCoverage=\(String(format: "%.1f%%", optimized.targetCoverage * 100)) placed=\(best.placements.count) unplaced=\(best.unplaced.count) \(NestEngine.coverageDiagnosticText(for: best)) \(ManualLayoutTargets.diagnosticText(for: best)) compactness=\(NestEngine.coverageText(for: best)) heightReach=\(NestEngine.heightReachText(for: best)) whitespacePenalty=\(best.stats.whitespacePenalty) elapsed=\(String(format: "%.3f", elapsed))s")
            AppLogger.shared.log(NestEngine.visualAuditLogLine(for: best))
            for line in best.debugLines {
                AppLogger.shared.log(line)
            }
            await MainActor.run {
                guard runID == self.optimizationRunID else { return }
                self.settings = finalSettings
                self.placements = best.placements
                self.stats = best.stats
                self.previewImage = self.renderPreview(drawGuides: true)
                self.saveLatestPreview()
                if best.unplaced.isEmpty {
                    self.saveAdaptiveScaleSnapshot(items: optimized.scaledItems, settings: finalSettings, result: best, targetCoverage: optimized.targetCoverage)
                }
                self.status = best.unplaced.isEmpty ? "单张缩放完成：\(NestEngine.coverageDiagnosticText(for: best))；\(visualAudit)" : "单张缩放仍有 \(best.unplaced.count) 张放不下；\(visualAudit)"
                self.statusColor = best.unplaced.isEmpty ? .secondary : .orange
                self.autoExportPSDIfRequested()
                self.activeOptimizationTask = nil
                self.isWorking = false
            }
        }
    }

    private func showOptimizationProgress(result: NestEngine.NestResult, settings: NestSettings, message: String, runID: Int? = nil) async {
        await MainActor.run {
            if let runID, runID != self.optimizationRunID {
                return
            }
            self.settings = settings
            self.placements = result.placements
            self.stats = result.stats
            self.previewImage = self.renderPreview(drawGuides: true)
            self.saveLatestPreview()
            self.status = message
            self.statusColor = result.unplaced.isEmpty ? .secondary : .orange
        }
    }

    nonisolated private static func runExternalAutoNest(
        items: [StickerItem],
        settings: NestSettings
    ) -> (result: NestEngine.NestResult, scaledItems: [StickerItem], targetCoverage: Double, settings: NestSettings)? {
        guard items.count >= 20 else { return nil }
        let scriptCandidates = [
            Bundle.main.resourceURL?.appendingPathComponent("auto_nest.py"),
            URL(fileURLWithPath: FileManager.default.currentDirectoryPath).appendingPathComponent("Tools/auto_nest.py")
        ].compactMap { $0 }
        guard let scriptURL = scriptCandidates.first(where: { FileManager.default.fileExists(atPath: $0.path) }) else {
            AppLogger.shared.log("external_auto_nest_missing_script")
            return nil
        }

        let runID = UUID().uuidString
        let workDir = AppPaths.supportDirectory.appendingPathComponent("external-auto-nest-\(runID)", isDirectory: true)
        let inputDir = workDir.appendingPathComponent("input", isDirectory: true)
        var nameMap: [String: String] = [:]

        do {
            try FileManager.default.createDirectory(at: inputDir, withIntermediateDirectories: true)
            for (index, item) in items.enumerated() {
                let cleanName = item.name.replacingOccurrences(of: "/", with: "_")
                let exportName = String(format: "%03d_", index) + (cleanName.hasSuffix(".png") ? cleanName : "\(cleanName).png")
                let url = inputDir.appendingPathComponent(exportName)
                guard let data = pngData(for: item.image) else {
                    AppLogger.shared.log("external_auto_nest_export_failed name=\(item.name)")
                    return nil
                }
                try data.write(to: url)
                nameMap[exportName] = item.name
            }

            let materialSavingModeSetting = ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_MATERIAL_SAVING_MODE"] ?? (settings.materialSavingMode ? "1" : "0")
            let materialSavingModeRequested = !["0", "false", "off", "no"].contains(materialSavingModeSetting.lowercased())
            let edgeSafetyExternalMode = settings.isTemplateMaterial && (settings.gapMM >= 5.5 || materialSavingModeRequested)
            let manualStaggerExternalMode = edgeSafetyExternalMode && items.count == 25
            let materialSavingModeEnabled = manualStaggerExternalMode && materialSavingModeRequested
            let defaultSeconds = edgeSafetyExternalMode ? 45.0 : 90.0
            let seconds = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_SECONDS"] ?? "") ?? defaultSeconds
            let defaultFallbackSeconds = edgeSafetyExternalMode ? 35.0 : min(45.0, max(30.0, seconds * 0.5))
            let fallbackSeconds = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_FALLBACK_SECONDS"] ?? "") ?? defaultFallbackSeconds
            let primaryExtraSeedSeconds = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_EXTRA_SEED_SECONDS"] ?? "") ?? (manualStaggerExternalMode ? 90.0 : fallbackSeconds)
            let rawMaterialSavingGapMM = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_MATERIAL_SAVING_GAP_MM"] ?? "") ?? min(settings.gapMM, 5.0)
            let materialSavingGapMM = max(3.0, min(settings.gapMM, rawMaterialSavingGapMM))
            let materialSavingTargetSetting = ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_MATERIAL_SAVING_TARGETS"] ?? "108,107"
            let materialSavingTargetValues = materialSavingTargetSetting
                .split(separator: ",")
                .compactMap { Double($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
                .filter { $0 >= 90.0 && $0 <= 120.0 }
            let rawMaterialSavingSeconds = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_MATERIAL_SAVING_SECONDS"] ?? "") ?? primaryExtraSeedSeconds
            let materialSavingSeconds = max(15.0, min(primaryExtraSeedSeconds, rawMaterialSavingSeconds))
            let materialSavingScaleProfileSetting = (ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_MATERIAL_SAVING_SCALE_PROFILE"] ?? "1").lowercased()
            let materialSavingScaleProfileEnabled = materialSavingModeEnabled
                && !["0", "false", "off", "no"].contains(materialSavingScaleProfileSetting)
            struct MaterialSavingScaleProfile {
                let visualMin: Double
                let visualPower: Double
                let visualMax: Double
                let label: String
            }
            let materialSavingSeedScaleProfiles: [Int: MaterialSavingScaleProfile] = materialSavingScaleProfileEnabled
                ? [3: MaterialSavingScaleProfile(visualMin: 1.00, visualPower: 0.15, visualMax: 1.10, label: "floor100")]
                : [:]
            let materialSavingAttemptSeeds = materialSavingScaleProfileEnabled ? [4, 3] : [4]
            let minScale = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_MIN_SCALE"] ?? "") ?? 0.90
            let maxScale = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_MAX_SCALE"] ?? "") ?? 1.18
            let defaultAcceptAlpha = manualStaggerExternalMode ? 0.500 : 0.540
            let acceptAlpha = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_ACCEPT_ALPHA"] ?? "") ?? defaultAcceptAlpha
            let defaultSeedCount = manualStaggerExternalMode ? 5 : (edgeSafetyExternalMode ? 3 : 1)
            let seedCount = max(1, min(8, Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_SEEDS"] ?? "") ?? defaultSeedCount))
            let preferredVisualScore = Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PREFERRED_VISUAL_SCORE"] ?? "") ?? 72
            let continueLowerTargetsUntilScore = Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_CONTINUE_LOWER_UNTIL_SCORE"] ?? "") ?? 60
            let lowerTargetStopAlpha = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_LOWER_STOP_ALPHA"] ?? "") ?? 0.535
            let lowerTargetStopDelta = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_LOWER_STOP_DELTA_MM"] ?? "") ?? 2.0
            let defaultLowerSeedCount = manualStaggerExternalMode ? 2 : 1
            let lowerSeedCount = max(1, min(4, Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_LOWER_SEEDS"] ?? "") ?? defaultLowerSeedCount))
            let lowerSeedMaxDelta = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_LOWER_SEED_MAX_DELTA_MM"] ?? "") ?? 2.5
            let lowerExtraSeedMinDelta = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_LOWER_EXTRA_SEED_MIN_DELTA_MM"] ?? "") ?? 2.0
            let lowerFastStopScoreGain = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_LOWER_FAST_STOP_SCORE_GAIN"] ?? "") ?? 100.0
            let lowerFastStopVisualGain = Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_LOWER_FAST_STOP_VISUAL_GAIN"] ?? "") ?? 3
            let primaryMaterialStopAlpha = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_STOP_ALPHA"] ?? "") ?? (manualStaggerExternalMode ? 0.546 : 1.0)
            let primaryMaterialStopVisualFloor = Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_STOP_VISUAL_FLOOR"] ?? "") ?? 50
            let primaryMaterialStopMinReadable = Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_STOP_MIN_READABLE"] ?? "") ?? 20
            let primaryMaterialStopMaxUpside = Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_STOP_MAX_UPSIDE"] ?? "") ?? 6
            let primaryMaterialStopMaxSideways = Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_STOP_MAX_SIDEWAYS"] ?? "") ?? 1
            let primaryMaterialStopMaxHard = Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_STOP_MAX_HARD"] ?? "") ?? 5
            let primaryMaterialProtectAlpha = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_PROTECT_ALPHA"] ?? "") ?? (manualStaggerExternalMode ? 0.550 : primaryMaterialStopAlpha)
            let primaryMaterialTopupDefault = manualStaggerExternalMode ? "1" : "0"
            let primaryMaterialTopupSetting = (ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_TOPUP"] ?? primaryMaterialTopupDefault).lowercased()
            let primaryMaterialTopupEnabled = manualStaggerExternalMode && !["0", "false", "off", "no"].contains(primaryMaterialTopupSetting)
            let primaryMaterialTopupTargetAlpha = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_TOPUP_TARGET_ALPHA"] ?? "") ?? (manualStaggerExternalMode ? 0.5515 : primaryMaterialProtectAlpha)
            let primaryMaterialTopupMinGain = Double(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_TOPUP_MIN_GAIN"] ?? "") ?? (manualStaggerExternalMode ? 0.0015 : 0.0)
            let primaryMaterialTopupMaxMoves = max(1, min(24, Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_TOPUP_MAX_MOVES"] ?? "") ?? (manualStaggerExternalMode ? 16 : 8)))
            let primaryMaterialTopupMaxNudge = max(0, min(6, Int(ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_PRIMARY_MATERIAL_TOPUP_MAX_NUDGE"] ?? "") ?? (manualStaggerExternalMode ? 4 : 2)))
            let fallbackMaterialTopupDefault = manualStaggerExternalMode ? "1" : "0"
