            func primaryMaterialStopOrientationOK(_ stats: NestEngine.LayoutOrientationStats) -> Bool {
                stats.readable >= primaryMaterialStopMinReadable
                    && stats.upside <= primaryMaterialStopMaxUpside
                    && stats.sideways <= primaryMaterialStopMaxSideways
                    && stats.hard <= primaryMaterialStopMaxHard
            }

            struct ExternalCandidate {
                let result: NestEngine.NestResult
                let scaledItems: [StickerItem]
                let targetCoverage: Double
                let settings: NestSettings
                let targetLongSideMM: Double
                let seed: Int
                let alpha: Double
                let audit: VisualAudit
                let orientationStats: NestEngine.LayoutOrientationStats
                let baseSelectionScore: Double
                let selectionScore: Double
                let readableVariant: Bool
                let safeAngleVariant: Bool
                let reusedPrimarySeed: Bool
                let orientationSelectionOK: Bool
                let materialTopupForAttempt: Bool
                let materialSavingTarget: Bool
                let polishPass: Int
                let outputURL: URL
            }
            var bestCandidate: ExternalCandidate?
            var lowAlphaReadableCandidate: ExternalCandidate?
            var materialSavingLowAlphaReadableCandidate: ExternalCandidate?

            struct ExternalAttemptSeed {
                let seedIndex: Int
                let seed: Int
                let reusedPrimarySeed: Bool
                let visualBalanceMin: Double?
                let visualBalancePower: Double?
                let visualBalanceMax: Double?
                let materialSavingScaleProfile: String?
            }

            struct ExternalAttemptVariant {
                let readableVariant: Bool
                let manualRotate: Bool
                let safeAngleVariant: Bool

                var outputSuffix: String {
                    if readableVariant { return "-rotate0" }
                    if safeAngleVariant { return "-safeangle" }
                    return ""
                }
                var logLabel: String {
                    if readableVariant { return "readable_no_rotate" }
                    if safeAngleVariant { return "safe_angle" }
                    return "normal"
                }
            }

            struct ExternalTargetCandidate {
                let targetLongSideMM: Double
                let gapMM: Double?
                let materialSaving: Bool

                var outputNameToken: String {
                    let targetToken = "\(Int(round(targetLongSideMM * 10)))"
                    guard let gapMM else { return targetToken }
                    let gapToken = "gap\(Int(round(gapMM * 10)))"
                    return materialSaving ? "\(targetToken)-\(gapToken)-saving" : "\(targetToken)-\(gapToken)"
                }

                var logText: String {
                    let targetText = String(format: "%.1f", targetLongSideMM)
                    guard let gapMM else { return targetText }
                    let modeText = materialSaving ? ":materialSaving" : ""
                    return "\(targetText)@gap\(String(format: "%.1f", gapMM))\(modeText)"
                }
            }

            var targetCandidates: [ExternalTargetCandidate] = []
            func addTarget(_ value: Double, gapMM: Double? = nil, materialSaving: Bool = false) {
                guard value > 20 else { return }
                let candidate = ExternalTargetCandidate(targetLongSideMM: value, gapMM: gapMM, materialSaving: materialSaving)
                if !targetCandidates.contains(where: {
                    abs($0.targetLongSideMM - candidate.targetLongSideMM) < 0.05
                        && abs(($0.gapMM ?? settings.gapMM) - (candidate.gapMM ?? settings.gapMM)) < 0.05
                        && $0.materialSaving == candidate.materialSaving
                }) {
                    targetCandidates.append(candidate)
                }
            }
            if materialSavingModeEnabled {
                for target in materialSavingTargetValues {
                    addTarget(target, gapMM: materialSavingGapMM, materialSaving: true)
                }
            }
            if let configuredTargets = ProcessInfo.processInfo.environment["STICKERNEST_EXTERNAL_TARGETS"] {
                configuredTargets
                    .split(separator: ",")
                    .compactMap { Double($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
                    .forEach { addTarget($0) }
            } else if edgeSafetyExternalMode {
                if safeAngleHighTargetEnabled,
                   safeAngleHighTargetMM > settings.targetLongSideMM + safeAngleHighTargetMinDeltaMM {
                    addTarget(safeAngleHighTargetMM)
                }
                [settings.targetLongSideMM, 112.5, 112.0, 111.0]
                    .forEach { addTarget($0) }
                if highReadableRescueEnabled {
                    addTarget(highReadableRescueTargetMM)
                }
                [105.0, 104.0, 102.0]
                    .forEach { addTarget($0) }
            } else {
                addTarget(settings.targetLongSideMM)
            }

            func stableLowerTargetSeedBase(for targetLongSideMM: Double, attemptIndex: Int) -> Int {
                if abs(targetLongSideMM - 105.0) < 0.05 {
                    return 400
                }
                if abs(targetLongSideMM - 102.0) < 0.05 {
                    return 500
                }
                return attemptIndex * 100
            }

            // v1.1.234: a selected strict-readable low-alpha best (all 25 readable, 0 upside/
            // sideways/hard, alpha below the material-protect floor but at/above the low-alpha
            // floor) is allowed to run the low-alpha selected polish even when it came from a
            // material-topup attempt at polishPass 0 — offline POLISH_BASE_JSON proves the 108
            // strict-readable rescue can still gain material safely.
            func selectedStrictReadableLowAlphaPolishGate(_ candidate: ExternalCandidate) -> Bool {
                manualStaggerExternalMode
                    && lowAlphaReadablePostprocessEnabled
                    && candidate.result.unplaced.isEmpty
                    && candidate.result.placements.count == items.count
                    && candidate.orientationStats.readable == items.count
                    && candidate.orientationStats.upside == 0
                    && candidate.orientationStats.sideways == 0
                    && candidate.orientationStats.hard == 0
                    && candidate.alpha < primaryMaterialProtectAlpha
                    && candidate.alpha >= lowAlphaReadableMinAlpha
            }
            // v1.1.235: high-alpha strict-readable selected layouts can still have small safe
            // material gains in the selected JSON polish path. Keep this selected-only and reuse
            // the same strict rebuild/orientation/visual guards inside selectedMaterialTopupCandidate.
            func selectedStrictReadableMaterialPolishGate(_ candidate: ExternalCandidate) -> Bool {
                manualStaggerExternalMode
                    && lowAlphaReadablePostprocessEnabled
                    && candidate.result.unplaced.isEmpty
                    && candidate.result.placements.count == items.count
                    && candidate.orientationStats.readable == items.count
                    && candidate.orientationStats.upside == 0
                    && candidate.orientationStats.sideways == 0
                    && candidate.orientationStats.hard == 0
                    && candidate.alpha >= primaryMaterialProtectAlpha
            }
            func materialSavingStageStopCandidate(savedLowAlpha: ExternalCandidate?, currentBest: ExternalCandidate?) -> ExternalCandidate? {
                let currentBestCandidate: ExternalCandidate?
                if let currentBest,
                   currentBest.materialSavingTarget,
                   selectedStrictReadableLowAlphaPolishGate(currentBest) {
                    currentBestCandidate = currentBest
                } else {
                    currentBestCandidate = nil
                }
                guard let savedLowAlpha else { return currentBestCandidate }
                guard let currentBestCandidate else { return savedLowAlpha }
                if currentBestCandidate.alpha >= savedLowAlpha.alpha - 0.0005 {
                    return currentBestCandidate
                }
                return savedLowAlpha
            }
            // v1.1.242: keep a separate best material-saving low-alpha candidate.
            // The generic low-alpha tracker is score-oriented for later polish, but
            // stage-stop must not let a lower 107mm candidate overwrite a higher
            // 108mm material-saving candidate that is already the current best.
            func materialSavingLowAlphaCandidateShouldReplaceSaved(_ candidate: ExternalCandidate, saved: ExternalCandidate?) -> Bool {
                guard candidate.materialSavingTarget,
                      selectedStrictReadableLowAlphaPolishGate(candidate) else {
                    return false
                }
                guard let saved else { return true }
                if candidate.alpha > saved.alpha + 0.0005 {
                    return true
                }
                if abs(candidate.alpha - saved.alpha) <= 0.0005 {
                    return candidate.selectionScore > saved.selectionScore
                }
                return false
            }
            // v1.1.237: material-saving gap-relaxed candidates can be deliberately below the
            // standard 50% acceptance floor before selected low-alpha polish. Let them compete
            // after the guarded polish path, but only when they stay strict-readable and beat the
            // current non-protected best on alpha.
            func materialSavingLowAlphaPolishShouldReplaceBest(_ polishedCandidate: ExternalCandidate, currentBest: ExternalCandidate?) -> Bool {
                guard polishedCandidate.materialSavingTarget,
                      selectedStrictReadableLowAlphaPolishGate(polishedCandidate) else {
                    return false
                }
                guard let currentBest else { return true }
                if currentBest.alpha >= primaryMaterialProtectAlpha {
                    return false
                }
                return polishedCandidate.alpha > currentBest.alpha
            }
            // v1.1.238: if the selected low-alpha polish output is rejected by the
            // stricter Swift rebuild guard, still allow the original material-saving
            // candidate to win when it is already strict-readable and improves alpha.
            func materialSavingLowAlphaCandidateShouldReplaceBest(_ candidate: ExternalCandidate, currentBest: ExternalCandidate?) -> Bool {
                guard candidate.materialSavingTarget,
                      selectedStrictReadableLowAlphaPolishGate(candidate) else {
                    return false
                }
                guard let currentBest else { return true }
                if currentBest.alpha >= primaryMaterialProtectAlpha {
                    return false
                }
                return candidate.alpha > currentBest.alpha
            }
            // v1.1.241: the saved material-saving candidate may already be the
            // current best. Treat an alpha tie as enough to stop before the
            // normal ladder, while still protecting any high-alpha best.
            func materialSavingLowAlphaStageStopShouldStop(_ candidate: ExternalCandidate, currentBest: ExternalCandidate?) -> Bool {
                guard candidate.materialSavingTarget,
                      selectedStrictReadableLowAlphaPolishGate(candidate) else {
                    return false
                }
                guard let currentBest else { return true }
                if currentBest.alpha >= primaryMaterialProtectAlpha {
                    return false
                }
                return candidate.alpha >= currentBest.alpha - 0.0005
            }
            func selectedMaterialTopupCandidate(from bestCandidate: ExternalCandidate, lowAlphaReadable: Bool = false, allowStrictReadableLowAlphaPolish: Bool = false) -> ExternalCandidate? {
                let selectedMaterialTopupGuardOK = selectedMaterialTopupEnabled
                    && manualStaggerExternalMode
                    && primaryMaterialTopupEnabled
                    && (!bestCandidate.materialTopupForAttempt
                        || (lowAlphaReadable && bestCandidate.polishPass > 0)
                        || (lowAlphaReadable && allowStrictReadableLowAlphaPolish))
                    && bestCandidate.result.unplaced.isEmpty
                    && bestCandidate.result.placements.count == items.count
                guard selectedMaterialTopupGuardOK else { return nil }

                let effectiveTargetGain = lowAlphaReadable ? lowAlphaReadableSelectedMaterialTopupTargetGain : selectedMaterialTopupTargetGain
                let effectiveMaxDeficit = lowAlphaReadable ? lowAlphaReadableSelectedMaterialTopupMaxDeficit : selectedMaterialTopupMaxDeficit
                let effectiveMaxMoves = lowAlphaReadable ? lowAlphaReadableSelectedMaterialTopupMaxMoves : selectedMaterialTopupMaxMoves
                let effectiveMaxNudge = lowAlphaReadable ? lowAlphaReadableSelectedMaterialTopupMaxNudge : selectedMaterialTopupMaxNudge
                let effectiveSeconds = lowAlphaReadable ? lowAlphaReadableSelectedMaterialTopupSeconds : selectedMaterialTopupSeconds
                let effectiveMultiPieceMaxMoves = lowAlphaReadable ? lowAlphaReadableMultiPieceTopupMaxMoves : primaryMultiPieceTopupMaxMoves
                let effectiveMultiPieceMaxNudge = lowAlphaReadable ? lowAlphaReadableMultiPieceTopupMaxNudge : primaryMultiPieceTopupMaxNudge
                let effectiveMultiPieceNodeLimit = lowAlphaReadable ? lowAlphaReadableMultiPieceTopupNodeLimit : primaryMultiPieceTopupNodeLimit
                let effectiveMultiPieceTargets = lowAlphaReadable ? lowAlphaReadableMultiPieceTopupTargets : primaryMultiPieceTopupTargets
                let targetAlpha = lowAlphaReadable ? bestCandidate.alpha + effectiveTargetGain : max(bestCandidate.alpha + effectiveTargetGain, acceptAlpha)
                let minAcceptAlpha = bestCandidate.alpha + selectedMaterialTopupMinGain
                let lowAlphaReadableStructuralMicroGrowMinAccept = bestCandidate.alpha + lowAlphaReadableStructuralMicroGrowMinAcceptGain
                let lowAlphaReadableSmallGroupMaterialRepackMinAccept = bestCandidate.alpha + lowAlphaReadableSmallGroupMaterialRepackMinAcceptGain
                let lowAlphaReadableBandVoidFillMinAccept = bestCandidate.alpha + lowAlphaReadableBandVoidFillMinAcceptGain
                let nextPolishPass = bestCandidate.polishPass + 1
                let outputSuffix = bestCandidate.readableVariant ? "-rotate0" : (bestCandidate.safeAngleVariant ? "-safeangle" : "")
                let lowAlphaSuffix = lowAlphaReadable ? "-lowalpha" : ""
