                let outputURL = workDir.appendingPathComponent("layout-selected-topup\(lowAlphaSuffix)-seed\(bestCandidate.seed)-\(Int(round(bestCandidate.targetLongSideMM * 10)))\(outputSuffix)\(passSuffix).json")
                let process = Process()
