                            AppLogger.shared.log("external_auto_nest_selected_material_topup_rejected reason=cancelled seed=\(bestCandidate.seed) targetLongSideMM=\(String(format: "%.2f", bestCandidate.targetLongSideMM))")
                            return nil
                        }
                        if externalProcessMemoryLimitMB > 0,
                           Date().timeIntervalSince(lastMemoryCheck) >= 0.34 {
                            lastMemoryCheck = Date()
                            if let rssMB = Self.externalProcessRSSMB(pid: process.processIdentifier),
                               rssMB > externalProcessMemoryLimitMB {
