                        && candidate.alpha < primaryMaterialProtectAlpha && !isOrientationSafeUpgrade
                    if isBlockedByMaterialAlphaProtection {
                        AppLogger.shared.log("external_auto_nest_candidate_rejected_by_material_alpha_protection index=\(attemptIndex) seed=\(seed) seedIndex=\(seedIndex) reusedPrimarySeed=\(candidate.reusedPrimarySeed) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) readableVariant=\(candidate.readableVariant) safeAngleVariant=\(candidate.safeAngleVariant) alpha=\(String(format: "%.1f%%", candidate.alpha * 100)) floor=\(String(format: "%.1f%%", primaryMaterialProtectAlpha * 100)) currentBestAlpha=\(String(format: "%.1f%%", (bestCandidate?.alpha ?? 0) * 100)) visualScore=\(candidate.audit.score) selectionScore=\(String(format: "%.1f", candidate.selectionScore))")
                    }
                    let isNewBest: Bool
                    if routeTierSelectionEnabled {
                        // Route-tier path: routeTierReplacesBest already encodes tier dominance,
                        // the near-strict budget, and same-tier alpha-first ordering.
                        isNewBest = !isBlockedByMaterialAlphaProtection && !isBlockedByRouteTier
                    } else {
                        isNewBest = !isBlockedByMaterialAlphaProtection
                            && !isBlockedByOrientationSafeSelection
                            && (bestCandidate == nil || isOrientationSafeUpgrade || isSameTierBetter)
                    }
                    if isNewBest {
                        AppLogger.shared.log("external_auto_nest_candidate_best index=\(attemptIndex) seed=\(seed) seedIndex=\(seedIndex) reusedPrimarySeed=\(candidate.reusedPrimarySeed) orientationSelectionOK=\(candidate.orientationSelectionOK) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) readableVariant=\(candidate.readableVariant) safeAngleVariant=\(candidate.safeAngleVariant) visualScore=\(audit.score) alpha=\(String(format: "%.1f%%", alpha * 100)) selectionScore=\(String(format: "%.1f", selectionScore)) baseSelectionScore=\(String(format: "%.1f", baseSelectionScore)) \(orientationStats.logText)")
                        bestCandidate = candidate
                    }
                    // Route-tier guard (v1.1.232): a not-strict (tier < 2) candidate must not
                    // stop the candidate pool. primaryMaterialStopOrientationOK still allows up to
                    // upside<=6/sideways<=1/hard<=5 (the tier1 budget), so without this guard a
                    // tier1 layout (e.g. test3 readable=20,upside=5,hard=5) would fast-stop before
                    // seed4 / the readable_no_rotate rescue / lower targets ever ran. When route-tier
                    // selection is on we only let a strict-readable (tier2) candidate fast-stop.
                    let candidateAllowsPrimaryStop = !routeTierSelectionEnabled || candidateRouteTier >= 3
                    if isPrimaryTarget,
                       manualStaggerExternalMode,
                       isNewBest,
                       routeTierSelectionEnabled,
                       !candidateAllowsPrimaryStop,
                       candidate.alpha >= primaryMaterialStopAlpha,
                       candidate.audit.score >= primaryMaterialStopVisualFloor,
                       primaryMaterialStopOrientationOK(candidate.orientationStats) {
                        AppLogger.shared.log("external_auto_nest_primary_material_stop_held_for_strict_tier index=\(attemptIndex) seed=\(seed) seedIndex=\(seedIndex) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) candidateTier=\(candidateRouteTier) alpha=\(String(format: "%.1f%%", candidate.alpha * 100)) visualScore=\(candidate.audit.score) \(candidate.orientationStats.logText)")
                    }
                    if isPrimaryTarget,
                       manualStaggerExternalMode,
                       isNewBest,
                       candidateAllowsPrimaryStop,
                       candidate.alpha >= primaryMaterialStopAlpha,
                       candidate.alpha >= primaryMaterialProtectAlpha,
                       candidate.audit.score >= primaryMaterialStopVisualFloor,
                       primaryMaterialStopOrientationOK(candidate.orientationStats) {
                        if shouldRunSafeAngleRescueVariant && !attemptVariant.safeAngleVariant {
                            primaryMaterialFastStopDeferredForSafeAngle = true
                            AppLogger.shared.log("external_auto_nest_primary_material_fast_stop_deferred_for_safe_angle index=\(attemptIndex) seed=\(seed) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) alpha=\(String(format: "%.1f%%", candidate.alpha * 100)) visualScore=\(candidate.audit.score) selectionScore=\(String(format: "%.1f", candidate.selectionScore)) floorAlpha=\(String(format: "%.1f%%", primaryMaterialProtectAlpha * 100)) visualFloor=\(primaryMaterialStopVisualFloor) \(candidate.orientationStats.logText)")
                            continue
                        }
                        stopAfterCurrentTarget = true
                        let remainingSeeds = seedsForTarget - seedIndex - 1
                        if primaryMaterialLookaheadUntilSeedIndex == nil,
                           primaryVisualLookaheadSeeds > 0,
                           remainingSeeds > 0 {
                            let lookaheadUntil = min(seedsForTarget - 1, seedIndex + primaryVisualLookaheadSeeds)
                            primaryMaterialLookaheadUntilSeedIndex = lookaheadUntil
                            stopAfterCurrentTargetReason = "primary_material_visual_lookahead"
                            AppLogger.shared.log("external_auto_nest_primary_material_visual_lookahead index=\(attemptIndex) seed=\(seed) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) alpha=\(String(format: "%.1f%%", candidate.alpha * 100)) visualScore=\(candidate.audit.score) selectionScore=\(String(format: "%.1f", candidate.selectionScore)) lookaheadUntilSeedIndex=\(lookaheadUntil) floorAlpha=\(String(format: "%.1f%%", primaryMaterialProtectAlpha * 100)) visualFloor=\(primaryMaterialStopVisualFloor) \(candidate.orientationStats.logText)")
                        } else {
                            AppLogger.shared.log("external_auto_nest_primary_material_fast_stop index=\(attemptIndex) seed=\(seed) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) alpha=\(String(format: "%.1f%%", candidate.alpha * 100)) visualScore=\(candidate.audit.score) selectionScore=\(String(format: "%.1f", candidate.selectionScore)) floorAlpha=\(String(format: "%.1f%%", primaryMaterialProtectAlpha * 100)) visualFloor=\(primaryMaterialStopVisualFloor) \(candidate.orientationStats.logText)")
                            stopAfterCurrentTargetReason = "primary_material_fast_stop"
                            break
                        }
                    }
                    if !isPrimaryTarget,
                       let previousBestCandidate,
                       (!shouldRunReadableNoRotateVariant || attemptVariant.readableVariant),
                       candidate.selectionScore >= previousBestCandidate.selectionScore + lowerFastStopScoreGain,
                       candidate.audit.score >= previousBestCandidate.audit.score + lowerFastStopVisualGain,
                       candidate.alpha >= lowerTargetStopAlpha {
                        AppLogger.shared.log("external_auto_nest_lower_fast_stop index=\(attemptIndex) seed=\(seed) seedIndex=\(seedIndex) reusedPrimarySeed=\(candidate.reusedPrimarySeed) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) reason=lower_candidate_clear_improvement visualScore=\(candidate.audit.score) previousVisualScore=\(previousBestCandidate.audit.score) selectionScore=\(String(format: "%.1f", candidate.selectionScore)) previousSelectionScore=\(String(format: "%.1f", previousBestCandidate.selectionScore)) scoreGain=\(String(format: "%.1f", candidate.selectionScore - previousBestCandidate.selectionScore)) requiredScoreGain=\(String(format: "%.1f", lowerFastStopScoreGain))")
                        stopAfterCurrentTarget = true
                        stopAfterCurrentTargetReason = "lower_fast_stop"
                        break
                    }
                    }
                    if primaryMaterialFastStopDeferredForSafeAngle && !stopAfterCurrentTarget {
                        stopAfterCurrentTarget = true
                        stopAfterCurrentTargetReason = "primary_material_fast_stop_after_safe_angle"
                        AppLogger.shared.log("external_auto_nest_primary_material_fast_stop_after_safe_angle index=\(attemptIndex) seed=\(seed) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) bestAlpha=\(String(format: "%.1f%%", (bestCandidate?.alpha ?? 0) * 100)) bestVisualScore=\(bestCandidate?.audit.score ?? -1)")
                    }
                    if stopAfterCurrentTarget {
                        break
                    }
                }
                if stopAfterCurrentTarget {
                    AppLogger.shared.log("external_auto_nest_candidate_pool_stop_after_target reason=\(stopAfterCurrentTargetReason) targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) bestVisualScore=\(bestCandidate?.audit.score ?? -1) bestAlpha=\(String(format: "%.1f%%", (bestCandidate?.alpha ?? 0) * 100))")
                    break
                }
                let nextTargetIsMaterialSaving = attemptIndex + 1 < targetCandidates.count && targetCandidates[attemptIndex + 1].materialSaving
                if isMaterialSavingTarget,
                   nextTargetIsMaterialSaving,
                   let materialSavingStageStopCandidate = materialSavingStageStopCandidate(savedLowAlpha: materialSavingLowAlphaReadableCandidate, currentBest: bestCandidate),
                   materialSavingLowAlphaStageStopShouldStop(materialSavingStageStopCandidate, currentBest: bestCandidate) {
                    AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_stop_before_lower_targets targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) nextTargetLongSideMM=\(String(format: "%.2f", targetCandidates[attemptIndex + 1].targetLongSideMM)) savedTargetLongSideMM=\(String(format: "%.2f", materialSavingStageStopCandidate.targetLongSideMM)) savedAlpha=\(String(format: "%.2f%%", materialSavingStageStopCandidate.alpha * 100)) currentBestAlpha=\(String(format: "%.2f%%", (bestCandidate?.alpha ?? 0) * 100)) \(materialSavingStageStopCandidate.orientationStats.logText)")
                    break
                }
                if isMaterialSavingTarget,
                   !nextTargetIsMaterialSaving,
                   let materialSavingStageStopCandidate = materialSavingStageStopCandidate(savedLowAlpha: materialSavingLowAlphaReadableCandidate, currentBest: bestCandidate),
                   materialSavingLowAlphaStageStopShouldStop(materialSavingStageStopCandidate, currentBest: bestCandidate) {
                    AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_stop_before_normal_targets targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) savedTargetLongSideMM=\(String(format: "%.2f", materialSavingStageStopCandidate.targetLongSideMM)) savedAlpha=\(String(format: "%.2f%%", materialSavingStageStopCandidate.alpha * 100)) currentBestAlpha=\(String(format: "%.2f%%", (bestCandidate?.alpha ?? 0) * 100)) \(materialSavingStageStopCandidate.orientationStats.logText)")
                    break
                }
                let isCurrentPrimaryTarget = abs(targetLongSideMM - settings.targetLongSideMM) < 0.05
                if let bestCandidate,
                   targetLongSideMM <= settings.targetLongSideMM + 0.05,
                   bestCandidate.audit.score >= preferredVisualScore {
                    AppLogger.shared.log("external_auto_nest_candidate_pool_early_stop reason=preferred_visual_score score=\(bestCandidate.audit.score) threshold=\(preferredVisualScore)")
                    break
                }
                if let bestCandidate, isCurrentPrimaryTarget {
                    // Route-tier guard (v1.1.232): don't stop before lower targets while the best
                    // is not strict-readable (tier < 2). The lower targets + readable_no_rotate
                    // variants are where a fully upright (tier2) rescue is most likely, and
                    // route-tier selection will let that tier2 replace the current tier1.
                    let bestStrictTier = routeTierSelectionEnabled
                        ? NestEngine.externalRouteSelectionTier(
                            orientationStats: bestCandidate.orientationStats,
                            placementCount: bestCandidate.result.placements.count,
                            manualStagger: manualStaggerExternalMode,
                            nearStrictEnabled: routeNearStrictSelectionEnabled
                        )
                        : 3
                    if routeTierSelectionEnabled, bestStrictTier < 3 {
                        AppLogger.shared.log("external_auto_nest_candidate_pool_continue_to_lower_targets reason=best_tier_below_strict bestTier=\(bestStrictTier) bestVisualScore=\(bestCandidate.audit.score) bestAlpha=\(String(format: "%.1f%%", bestCandidate.alpha * 100)) \(bestCandidate.orientationStats.logText)")
                    } else if bestCandidate.audit.score >= continueLowerTargetsUntilScore {
                        AppLogger.shared.log("external_auto_nest_candidate_pool_stop_before_lower_targets reason=valid_primary_candidate bestVisualScore=\(bestCandidate.audit.score) threshold=\(continueLowerTargetsUntilScore)")
                        break
                    } else {
                        AppLogger.shared.log("external_auto_nest_candidate_pool_continue_to_lower_targets reason=primary_visual_below_floor bestVisualScore=\(bestCandidate.audit.score) threshold=\(continueLowerTargetsUntilScore)")
                    }
                }
                if let bestCandidate,
                   !isCurrentPrimaryTarget,
                   targetLongSideMM <= settings.targetLongSideMM - lowerTargetStopDelta,
                   bestCandidate.alpha >= lowerTargetStopAlpha,
                   (!manualStaggerExternalMode || primaryMaterialStopOrientationOK(bestCandidate.orientationStats)) {
                    AppLogger.shared.log("external_auto_nest_candidate_pool_stop_after_lower_target reason=lower_alpha_floor targetLongSideMM=\(String(format: "%.2f", targetLongSideMM)) bestVisualScore=\(bestCandidate.audit.score) bestAlpha=\(String(format: "%.1f%%", bestCandidate.alpha * 100)) floor=\(String(format: "%.1f%%", lowerTargetStopAlpha * 100))")
                    break
                }
            }
            if let currentBest = bestCandidate,
               let polishedCandidate = selectedMaterialTopupCandidate(from: currentBest, lowAlphaReadable: false) {
                bestCandidate = polishedCandidate
            }
            // v1.1.235: if the selected layout is already strict-readable and above the material
            // protection floor, give the stricter readable polish chain one selected-only pass.
            // This lets scale-transfer reclaim tiny safe gaps without admitting unreadable rotations.
            if let currentBest = bestCandidate,
               selectedStrictReadableMaterialPolishGate(currentBest) {
                AppLogger.shared.log("external_auto_nest_selected_strict_readable_material_polish_begin seed=\(currentBest.seed) targetLongSideMM=\(String(format: "%.2f", currentBest.targetLongSideMM)) alpha=\(String(format: "%.2f%%", currentBest.alpha * 100)) protectAlpha=\(String(format: "%.2f%%", primaryMaterialProtectAlpha * 100)) materialTopupForAttempt=\(currentBest.materialTopupForAttempt) polishPass=\(currentBest.polishPass) \(currentBest.orientationStats.logText)")
                if let polishedCandidate = selectedMaterialTopupCandidate(from: currentBest, lowAlphaReadable: true, allowStrictReadableLowAlphaPolish: true) {
                    AppLogger.shared.log("external_auto_nest_selected_strict_readable_material_polish_accept seed=\(polishedCandidate.seed) targetLongSideMM=\(String(format: "%.2f", polishedCandidate.targetLongSideMM)) previousAlpha=\(String(format: "%.2f%%", currentBest.alpha * 100)) alpha=\(String(format: "%.2f%%", polishedCandidate.alpha * 100)) \(polishedCandidate.orientationStats.logText)")
                    bestCandidate = polishedCandidate
                } else {
                    AppLogger.shared.log("external_auto_nest_selected_strict_readable_material_polish_reject seed=\(currentBest.seed) targetLongSideMM=\(String(format: "%.2f", currentBest.targetLongSideMM)) alpha=\(String(format: "%.2f%%", currentBest.alpha * 100))")
                }
            }
            // v1.1.234: selected strict-readable low-alpha polish. The normal polish above is
            // skipped for a material-topup-attempt best (its guard rejects materialTopupForAttempt
            // at polishPass 0), so a strict-readable but low-alpha selection — e.g. the 108
            // high-readable rescue — never got its low-alpha selected polish. Run it here, keeping
            // every existing quality guard (25/25 rebuild, alpha gain, orientation-not-worse,
            // strict-safe, visual-loss) inside selectedMaterialTopupCandidate.
            if let currentBest = bestCandidate,
               selectedStrictReadableLowAlphaPolishGate(currentBest) {
                AppLogger.shared.log("external_auto_nest_selected_strict_readable_low_alpha_polish_begin seed=\(currentBest.seed) targetLongSideMM=\(String(format: "%.2f", currentBest.targetLongSideMM)) alpha=\(String(format: "%.2f%%", currentBest.alpha * 100)) protectAlpha=\(String(format: "%.2f%%", primaryMaterialProtectAlpha * 100)) lowAlphaFloor=\(String(format: "%.2f%%", lowAlphaReadableMinAlpha * 100)) materialTopupForAttempt=\(currentBest.materialTopupForAttempt) polishPass=\(currentBest.polishPass) \(currentBest.orientationStats.logText)")
                if let polishedCandidate = selectedMaterialTopupCandidate(from: currentBest, lowAlphaReadable: true, allowStrictReadableLowAlphaPolish: true) {
                    AppLogger.shared.log("external_auto_nest_selected_strict_readable_low_alpha_polish_accept seed=\(polishedCandidate.seed) targetLongSideMM=\(String(format: "%.2f", polishedCandidate.targetLongSideMM)) previousAlpha=\(String(format: "%.2f%%", currentBest.alpha * 100)) alpha=\(String(format: "%.2f%%", polishedCandidate.alpha * 100)) \(polishedCandidate.orientationStats.logText)")
                    bestCandidate = polishedCandidate
                    if lowAlphaReadableIterativeSelectedPolishEnabled {
                        var currentPolishedCandidate = polishedCandidate
                        while currentPolishedCandidate.polishPass < lowAlphaReadableSelectedPolishPasses {
                            AppLogger.shared.log("external_auto_nest_selected_strict_readable_low_alpha_polish_iteration seed=\(currentPolishedCandidate.seed) targetLongSideMM=\(String(format: "%.2f", currentPolishedCandidate.targetLongSideMM)) nextPolishPass=\(currentPolishedCandidate.polishPass + 1) alpha=\(String(format: "%.2f%%", currentPolishedCandidate.alpha * 100))")
                            guard let nextPolishedCandidate = selectedMaterialTopupCandidate(from: currentPolishedCandidate, lowAlphaReadable: true, allowStrictReadableLowAlphaPolish: true) else {
                                break
                            }
                            bestCandidate = nextPolishedCandidate
                            currentPolishedCandidate = nextPolishedCandidate
                        }
                    }
                } else {
                    AppLogger.shared.log("external_auto_nest_selected_strict_readable_low_alpha_polish_reject seed=\(currentBest.seed) targetLongSideMM=\(String(format: "%.2f", currentBest.targetLongSideMM)) alpha=\(String(format: "%.2f%%", currentBest.alpha * 100))")
                }
            }
            if let materialSavingLowAlphaReadableCandidate = materialSavingStageStopCandidate(savedLowAlpha: materialSavingLowAlphaReadableCandidate, currentBest: bestCandidate),
               selectedStrictReadableLowAlphaPolishGate(materialSavingLowAlphaReadableCandidate) {
                AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_polish_begin seed=\(materialSavingLowAlphaReadableCandidate.seed) targetLongSideMM=\(String(format: "%.2f", materialSavingLowAlphaReadableCandidate.targetLongSideMM)) alpha=\(String(format: "%.2f%%", materialSavingLowAlphaReadableCandidate.alpha * 100)) currentBestAlpha=\(String(format: "%.2f%%", (bestCandidate?.alpha ?? 0) * 100)) lowAlphaFloor=\(String(format: "%.2f%%", lowAlphaReadableMinAlpha * 100)) materialTopupForAttempt=\(materialSavingLowAlphaReadableCandidate.materialTopupForAttempt) \(materialSavingLowAlphaReadableCandidate.orientationStats.logText)")
                var materialSavingPolishReplacedBest = false
                if let polishedCandidate = selectedMaterialTopupCandidate(from: materialSavingLowAlphaReadableCandidate, lowAlphaReadable: true, allowStrictReadableLowAlphaPolish: true) {
                    var currentPolishedCandidate = polishedCandidate
                    if lowAlphaReadableIterativeSelectedPolishEnabled {
                        while currentPolishedCandidate.polishPass < lowAlphaReadableSelectedPolishPasses {
                            AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_polish_iteration seed=\(currentPolishedCandidate.seed) targetLongSideMM=\(String(format: "%.2f", currentPolishedCandidate.targetLongSideMM)) nextPolishPass=\(currentPolishedCandidate.polishPass + 1) alpha=\(String(format: "%.2f%%", currentPolishedCandidate.alpha * 100))")
                            guard let nextPolishedCandidate = selectedMaterialTopupCandidate(from: currentPolishedCandidate, lowAlphaReadable: true, allowStrictReadableLowAlphaPolish: true) else {
                                break
                            }
                            currentPolishedCandidate = nextPolishedCandidate
                        }
                    }
                    if materialSavingLowAlphaPolishShouldReplaceBest(currentPolishedCandidate, currentBest: bestCandidate) {
                        AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_polish_accept seed=\(currentPolishedCandidate.seed) targetLongSideMM=\(String(format: "%.2f", currentPolishedCandidate.targetLongSideMM)) previousBestAlpha=\(String(format: "%.2f%%", (bestCandidate?.alpha ?? 0) * 100)) alpha=\(String(format: "%.2f%%", currentPolishedCandidate.alpha * 100)) \(currentPolishedCandidate.orientationStats.logText)")
                        bestCandidate = currentPolishedCandidate
                        materialSavingPolishReplacedBest = true
                    } else {
                        AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_polish_reject seed=\(currentPolishedCandidate.seed) targetLongSideMM=\(String(format: "%.2f", currentPolishedCandidate.targetLongSideMM)) currentBestAlpha=\(String(format: "%.2f%%", (bestCandidate?.alpha ?? 0) * 100)) alpha=\(String(format: "%.2f%%", currentPolishedCandidate.alpha * 100))")
                    }
                } else {
                    AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_polish_reject seed=\(materialSavingLowAlphaReadableCandidate.seed) targetLongSideMM=\(String(format: "%.2f", materialSavingLowAlphaReadableCandidate.targetLongSideMM)) alpha=\(String(format: "%.2f%%", materialSavingLowAlphaReadableCandidate.alpha * 100)) reason=postprocess_rejected")
                }
                if !materialSavingPolishReplacedBest {
                    if materialSavingLowAlphaCandidateShouldReplaceBest(materialSavingLowAlphaReadableCandidate, currentBest: bestCandidate) {
                        AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_raw_accept seed=\(materialSavingLowAlphaReadableCandidate.seed) targetLongSideMM=\(String(format: "%.2f", materialSavingLowAlphaReadableCandidate.targetLongSideMM)) previousBestAlpha=\(String(format: "%.2f%%", (bestCandidate?.alpha ?? 0) * 100)) alpha=\(String(format: "%.2f%%", materialSavingLowAlphaReadableCandidate.alpha * 100)) \(materialSavingLowAlphaReadableCandidate.orientationStats.logText)")
                        bestCandidate = materialSavingLowAlphaReadableCandidate
                    } else {
                        AppLogger.shared.log("external_auto_nest_material_saving_low_alpha_raw_reject seed=\(materialSavingLowAlphaReadableCandidate.seed) targetLongSideMM=\(String(format: "%.2f", materialSavingLowAlphaReadableCandidate.targetLongSideMM)) currentBestAlpha=\(String(format: "%.2f%%", (bestCandidate?.alpha ?? 0) * 100)) alpha=\(String(format: "%.2f%%", materialSavingLowAlphaReadableCandidate.alpha * 100))")
                    }
                }
            }
            if bestCandidate == nil,
               let lowAlphaReadableCandidate,
               let polishedCandidate = selectedMaterialTopupCandidate(from: lowAlphaReadableCandidate, lowAlphaReadable: true) {
                bestCandidate = polishedCandidate
                if lowAlphaReadableIterativeSelectedPolishEnabled {
                    var currentPolishedCandidate = polishedCandidate
                    while currentPolishedCandidate.polishPass < lowAlphaReadableSelectedPolishPasses {
                        AppLogger.shared.log("external_auto_nest_selected_material_topup_iteration seed=\(currentPolishedCandidate.seed) targetLongSideMM=\(String(format: "%.2f", currentPolishedCandidate.targetLongSideMM)) nextPolishPass=\(currentPolishedCandidate.polishPass + 1) alpha=\(String(format: "%.2f%%", currentPolishedCandidate.alpha * 100))")
                        guard let nextPolishedCandidate = selectedMaterialTopupCandidate(from: currentPolishedCandidate, lowAlphaReadable: true) else {
                            break
                        }
                        bestCandidate = nextPolishedCandidate
                        currentPolishedCandidate = nextPolishedCandidate
                    }
                }
            }
            if let bestCandidate {
                AppLogger.shared.log("external_auto_nest_candidate_pool_selected targetLongSideMM=\(String(format: "%.2f", bestCandidate.targetLongSideMM)) seed=\(bestCandidate.seed) reusedPrimarySeed=\(bestCandidate.reusedPrimarySeed) readableVariant=\(bestCandidate.readableVariant) safeAngleVariant=\(bestCandidate.safeAngleVariant) orientationSelectionOK=\(bestCandidate.orientationSelectionOK) alpha=\(String(format: "%.1f%%", bestCandidate.alpha * 100)) visualScore=\(bestCandidate.audit.score) selectionScore=\(String(format: "%.1f", bestCandidate.selectionScore)) baseSelectionScore=\(String(format: "%.1f", bestCandidate.baseSelectionScore)) \(bestCandidate.orientationStats.logText) \(NestEngine.coverageDiagnosticText(for: bestCandidate.result))")
                return (bestCandidate.result, bestCandidate.scaledItems, bestCandidate.targetCoverage, bestCandidate.settings)
            }
            AppLogger.shared.log("external_auto_nest_candidate_pool_empty action=swift_solver")
            return nil
        } catch {
            AppLogger.shared.log("external_auto_nest_failed error=\(error.localizedDescription)")
            return nil
        }
    }

    nonisolated private static func pngData(for image: CGImage) -> Data? {
        NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:])
    }

    private func saveLatestPreview() {
        guard let image = previewImage, let data = image.pngData else { return }
        let url = AppPaths.supportDirectory.appendingPathComponent("latest-preview.png")
        do {
            try data.write(to: url)
            AppLogger.shared.log("latest_preview_saved file=\(url.path)")
        } catch {
            AppLogger.shared.log("latest_preview_failed error=\(error.localizedDescription)")
        }
    }

    private func autoExportPSDIfRequested() {
        guard let path = ProcessInfo.processInfo.environment["STICKERNEST_AUTO_EXPORT_PSD"],
              !path.isEmpty,
              !placements.isEmpty
        else { return }
        let url = URL(fileURLWithPath: path)
        do {
            try writePSD(to: url)
            AppLogger.shared.log("auto_export_psd_success file=\(url.path) layers=\(exportPSDLayerCount)")
        } catch {
            AppLogger.shared.log("auto_export_psd_failed error=\(error.localizedDescription)")
        }
        if ProcessInfo.processInfo.environment["STICKERNEST_AUTO_QUIT_AFTER_EXPORT"] == "1" {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) {
                NSApp.terminate(nil)
            }
        }
    }

    private func saveAdaptiveScaleSnapshot(items: [StickerItem], settings: NestSettings, result: NestEngine.NestResult, targetCoverage: Double) {
        let records = items.map { item in
            AdaptiveScaleRecord(
                name: item.name,
                relativeScale: item.relativeScale,
                longSideMM: settings.targetLongSideMM * item.relativeScale,
                sourceWidth: item.width,
                sourceHeight: item.height,
                sourceAlphaArea: item.alphaArea
            )
        }
        let cell = result.stats.cell
        let placementRecords = result.placements.enumerated().map { index, placement in
            let xPX = (placement.gridX + placement.variant.gapCells) * cell
            let yPX = (placement.gridY + placement.variant.gapCells) * cell
            let widthPX = placement.variant.width
            let heightPX = placement.variant.height
            let centerXPX = Double(xPX) + Double(widthPX) / 2.0
            let centerYPX = Double(yPX) + Double(heightPX) / 2.0
            return PlacementRecord(
                index: index + 1,
                name: placement.item.name,
                angle: placement.variant.angle,
                relativeScale: placement.item.relativeScale,
                gridX: placement.gridX,
                gridY: placement.gridY,
                xPX: xPX,
                yPX: yPX,
                widthPX: widthPX,
                heightPX: heightPX,
                centerXPX: centerXPX,
                centerYPX: centerYPX,
                xMM: Double(xPX) / settings.pxPerMM,
                yMM: Double(yPX) / settings.pxPerMM,
                widthMM: Double(widthPX) / settings.pxPerMM,
                heightMM: Double(heightPX) / settings.pxPerMM,
                centerXMM: centerXPX / settings.pxPerMM,
                centerYMM: centerYPX / settings.pxPerMM,
                alphaPixels: placement.variant.alphaPixels
            )
        }
        let snapshot = AdaptiveScaleSnapshot(
            appVersion: AppInfo.displayVersion,
            createdAt: ISO8601DateFormatter().string(from: Date()),
            targetCoverage: targetCoverage,
            achievedCoverage: NestEngine.sheetCoverage(result),
            achievedAlphaCoverage: NestEngine.alphaPixelCoverage(result),
            achievedBboxCoverage: NestEngine.bboxPixelCoverage(result),
            achievedLayoutCoverage: NestEngine.layoutBBoxCoverage(result),
            targetLongSideMM: settings.targetLongSideMM,
            sheetWidthMM: settings.sheetWidthMM,
            sheetHeightMM: settings.sheetHeightMM,
            dpi: settings.dpi,
            gapMM: settings.gapMM,
            scalePercent: settings.scalePercent,
            angleStep: settings.angleStep,
            placedCount: result.placements.count,
            unplacedCount: result.unplaced.count,
            scales: records,
            placements: placementRecords
        )
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        let url = AppPaths.supportDirectory.appendingPathComponent("adaptive-scales.json")
        do {
            let data = try encoder.encode(snapshot)
            try data.write(to: url)
            AppLogger.shared.log("adaptive_scale_snapshot_saved file=\(url.path) records=\(records.count)")
        } catch {
            AppLogger.shared.log("adaptive_scale_snapshot_failed error=\(error.localizedDescription)")
        }
    }

    func saveCurrentLayoutAsManualSample() {
        guard !placements.isEmpty else {
            status = "当前还没有可记住的排版"
            statusColor = .orange
            return
        }
        let cell = stats?.cell ?? NestEngine.cellSize(for: settings)
        let sortedPlacements = placements.sorted {
            let lhsY = ($0.gridY + $0.variant.gapCells) * cell
            let rhsY = ($1.gridY + $1.variant.gapCells) * cell
            if abs(lhsY - rhsY) > max(24, cell * 8) {
                return lhsY < rhsY
            }
            return ($0.gridX + $0.variant.gapCells) < ($1.gridX + $1.variant.gapCells)
        }
        let matches: [ManualTargetProfile.Match] = sortedPlacements.map { placement in
            let xPX = (placement.gridX + placement.variant.gapCells) * cell
            let yPX = (placement.gridY + placement.variant.gapCells) * cell
            let widthPX = placement.variant.width
            let heightPX = placement.variant.height
            let manualLongSideMM = Double(max(widthPX, heightPX)) / settings.pxPerMM
            let sourceLongSide = max(1, max(placement.item.width, placement.item.height))
            let finalLongSide = max(1, max(widthPX, heightPX))
            return ManualTargetProfile.Match(
                sourceName: placement.item.name,
                confidence: "high",
                angleDegrees: Double(placement.variant.angle),
                manualLongSideMM: manualLongSideMM,
                scaleFromSourceCrop: Double(finalLongSide) / Double(sourceLongSide),
                center: ManualTargetProfile.Point(
                    x: Double(xPX) + Double(widthPX) / 2.0,
                    y: Double(yPX) + Double(heightPX) / 2.0
                ),
                bbox: ManualTargetProfile.BBox(x: xPX, y: yPX, w: widthPX, h: heightPX),
                sourceSize: ManualTargetProfile.SourceSize(w: placement.item.width, h: placement.item.height)
            )
        }
        let longSides = matches.map(\.manualLongSideMM)
        let profile = ManualTargetProfile(
            matchedCount: matches.count,
            highConfidenceCount: matches.count,
            medianManualLongSideMM: Self.median(longSides),
            meanManualLongSideMM: longSides.reduce(0, +) / Double(max(1, longSides.count)),
            sheet: ManualTargetProfile.Sheet(
                w: Double(settings.sheetWidthPX),
                h: Double(settings.sheetHeightPX)
            ),
            matches: matches
        )
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        let supportURL = AppPaths.supportDirectory.appendingPathComponent("manual_targets.json")
        let historyDirectory = AppPaths.supportDirectory.appendingPathComponent("manual_targets_history", isDirectory: true)
        let historyName = "manual-targets-\(Self.fileTimestamp()).json"
        let historyURL = historyDirectory.appendingPathComponent(historyName)
        do {
            try FileManager.default.createDirectory(at: historyDirectory, withIntermediateDirectories: true)
            let data = try encoder.encode(profile)
            try data.write(to: supportURL)
            try data.write(to: historyURL)
            let cacheURL = AppPaths.supportDirectory.appendingPathComponent("adaptive-scales.json")
            if FileManager.default.fileExists(atPath: cacheURL.path) {
                try? FileManager.default.removeItem(at: cacheURL)
                AppLogger.shared.log("manual_target_feedback_cache_cleared file=\(cacheURL.path)")
            }
            let portrait = profile.finalPortraitRatio * 100
            learningSummary = "已记住当前排版 \(matches.count) 张，竖向 \(String(format: "%.0f%%", portrait))。下次排版会优先参考这次角度和大小。"
            status = "已记住当前排版为人工样本"
            statusColor = .secondary
            AppLogger.shared.log("manual_target_feedback_saved file=\(supportURL.path) history=\(historyURL.path) matched=\(matches.count) portraitFinal=\(String(format: "%.3f", profile.finalPortraitRatio)) medianLongSideMM=\(String(format: "%.2f", profile.medianManualLongSideMM))")
        } catch {
            status = "记住当前排版失败：\(error.localizedDescription)"
            statusColor = .red
            AppLogger.shared.log("manual_target_feedback_failed error=\(error.localizedDescription)")
        }
    }

    private static func median(_ values: [Double]) -> Double {
        let sorted = values.filter { $0.isFinite }.sorted()
        guard !sorted.isEmpty else { return 0 }
        let mid = sorted.count / 2
        if sorted.count.isMultiple(of: 2) {
            return (sorted[mid - 1] + sorted[mid]) / 2.0
        }
        return sorted[mid]
    }

    private static func fileTimestamp() -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd-HHmmss"
        return formatter.string(from: Date())
    }

    func learnManualLayouts() {
        guard !isLearning else { return }
        isLearning = true
        status = "正在学习人工排版样本"
        statusColor = .secondary
        learningSummary = "正在读取 TIFF 二维码并匹配 PLT 刀线..."
        AppLogger.shared.log("manual_learning_begin")

        Task.detached(priority: .userInitiated) {
            let result = ManualLayoutLearner.run()
            await MainActor.run {
                self.isLearning = false
                switch result {
                case .success(let summary):
                    self.refreshLearningSummary()
                    self.status = "人工样本学习完成"
                    self.statusColor = .secondary
                    AppLogger.shared.log("manual_learning_success \(summary)")
                case .failure(let message):
                    self.learningSummary = "学习失败：\(message)"
                    self.status = "人工样本学习失败"
                    self.statusColor = .red
                    AppLogger.shared.log("manual_learning_failed \(message)")
                }
            }
        }
    }

    private func refreshLearningSummary() {
        let targetProfile = ManualTargetProfile.load()
        let targetText: String
        if let targetProfile {
            targetText = " 精确排版样本 \(targetProfile.matchedCount) 张，竖向 \(String(format: "%.0f%%", targetProfile.finalPortraitRatio * 100))。"
        } else {
            targetText = " 满意后点记住当前排版，才会变成新样本。"
        }
        if let profile = ManualLayoutProfile.load() {
            learningSummary = "已读取 \(profile.sampleCount) 个历史人工样本，二维码匹配 \(profile.qrPairCount) 个。\(profile.relationshipSummaryText)\(targetText)"
        } else {
            learningSummary = "还没有本地学习结果，点击学习人工样本。\(targetText)"
        }
    }

