    func exportPSD() {
        guard !placements.isEmpty else { return }
        let panel = NSSavePanel()
        panel.allowedContentTypes = [UTType(filenameExtension: "psd") ?? .data]
        panel.nameFieldStringValue = "异形排版.psd"
        if panel.runModal() == .OK, let url = panel.url {
            do {
                try writePSD(to: url)
                status = "已导出 PSD 图层"
