    private func writePSD(to url: URL) throws {
        let data = try makePSDData()
        try data.write(to: url)
    }

    private func makePSDData() throws -> Data {
        let cell = stats?.cell ?? NestEngine.cellSize(for: settings)
        let width = settings.sheetWidthPX
        let height = settings.sheetHeightPX
        var layers: [PSDExporter.Layer] = templatePSDLayers(width: width, height: height)
        layers.append(contentsOf: placements.enumerated().map { index, placement in
            let x = (placement.gridX + placement.variant.gapCells) * cell
            let y = (placement.gridY + placement.variant.gapCells) * cell
            return PSDExporter.Layer(
                name: "\(index + 1) \(placement.item.name)",
                image: placement.variant.image,
                left: x,
                top: y
            )
        })
        if settings.isTemplateMaterial {
            layers.append(contentsOf: templateOverlayPSDLayers())
        }
        return try PSDExporter.makePSD(width: width, height: height, layers: layers)
    }

    private var exportPSDLayerCount: Int {
        placements.count + (settings.isTemplateMaterial ? 1 + templateElements.count : 0)
    }

    private func templatePSDLayers(width: Int, height: Int) -> [PSDExporter.Layer] {
        guard settings.isTemplateMaterial,
              let background = solidImage(width: width, height: height, color: CGColor(gray: 1, alpha: 1))
        else { return [] }
        return [
            PSDExporter.Layer(name: "背景", image: background, left: 0, top: 0)
        ]
    }

    private func templateOverlayPSDLayers() -> [PSDExporter.Layer] {
        guard settings.isTemplateMaterial else { return [] }
        let template = templateCompositeImage()
        return templateElements.compactMap { element in
            guard let crop = templateElementImage(element, template: template) else { return nil }
            return PSDExporter.Layer(name: "模板 \(element.name)", image: crop, left: element.x, top: element.y)
        }
    }

    private func solidImage(width: Int, height: Int, color: CGColor) -> CGImage? {
        guard let context = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return nil }
        context.setFillColor(color)
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        return context.makeImage()
    }

    func clear() {
        items = []
        placements = []
        stats = nil
