    private func loadSticker(url: URL) -> StickerItem? {
        guard let image = NSImage(contentsOf: url),
              let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil),
              let cropped = ImageAlpha.cropTransparent(cgImage)
        else { return nil }
        let thumbnail = NSImage(cgImage: cropped.image, size: NSSize(width: 64, height: 64))
        let hasUsefulAlpha = cropped.alphaArea < cgImage.width * cgImage.height
        AppLogger.shared.log("item_loaded name=\(url.lastPathComponent) original=\(cgImage.width)x\(cgImage.height) cropped=\(cropped.image.width)x\(cropped.image.height) alphaArea=\(cropped.alphaArea) hasTransparentPixels=\(hasUsefulAlpha)")
        return StickerItem(
            name: url.lastPathComponent,
            image: cropped.image,
            thumbnail: thumbnail,
            originalWidth: cgImage.width,
            originalHeight: cgImage.height,
            width: cropped.image.width,
            height: cropped.image.height,
            alphaArea: cropped.alphaArea,
            relativeScale: 1,
            shapeClass: .block
        )
    }

    private func applyLearnedSizeVariation(_ loaded: [StickerItem]) -> [StickerItem] {
        guard loaded.count > 1 else { return loaded }
        let manualTargets = ManualTargetProfile.load()
        let manualMedian = manualTargets?.medianManualLongSideMM ?? 0
        let aspectValues = loaded.map { Double(max($0.width, $0.height)) / Double(max(1, min($0.width, $0.height))) }.sorted()
        let medianAspect = aspectValues[aspectValues.count / 2]
        let squareFills = loaded
            .map { Double($0.alphaArea) / pow(Double(max(1, max($0.width, $0.height))), 2.0) }
            .sorted()
        let medianSquareFill = max(0.0001, squareFills[squareFills.count / 2])
        return loaded.map { item in
            let aspect = Double(max(item.width, item.height)) / Double(max(1, min(item.width, item.height)))
            let shapeClass: ShapeClass
            if Double(item.height) / Double(max(1, item.width)) > 1.35 {
                shapeClass = .tall
            } else if Double(item.width) / Double(max(1, item.height)) > 1.35 {
                shapeClass = .wide
            } else {
                shapeClass = .block
            }
            let aspectDelta = min(0.035, max(-0.030, (aspect - medianAspect) * 0.012))
            let fillRatio = Double(item.alphaArea) / Double(max(1, item.width * item.height))
            let fillDelta = min(0.018, max(-0.018, (fillRatio - 0.68) * 0.035))
            let squareFill = max(0.0001, Double(item.alphaArea) / pow(Double(max(1, max(item.width, item.height))), 2.0))
            let visualAreaBalance = sqrt(medianSquareFill / squareFill) - 1.0
            let visualAreaDelta = min(0.120, max(-0.100, visualAreaBalance * 0.70))
            let classDelta: Double
            switch shapeClass {
            case .tall: classDelta = 0.010
            case .wide: classDelta = 0.006
            case .block: classDelta = -0.004
            }
            var scale = min(1.14, max(0.88, 1.0 + aspectDelta + fillDelta + visualAreaDelta + classDelta))
            if let manualTarget = manualTargets?.target(forName: item.name),
               manualMedian > 1,
               manualTarget.confidence != "low" {
                if manualTarget.matchesSource(item) {
                    let baseScale = scale
                    let rawManualScale = manualTarget.manualLongSideMM / manualMedian
                    let spaciousTemplateMode = settings.isTemplateMaterial && settings.gapMM >= 5.5 && loaded.count >= 25
                    let manualLower = spaciousTemplateMode ? 0.92 : 0.88
                    let manualUpper = 1.20
                    let manualBlend = spaciousTemplateMode ? 0.50 : 0.65
                    let manualScale = min(manualUpper, max(manualLower, rawManualScale))
                    let blended = baseScale * (1.0 - manualBlend) + manualScale * manualBlend
                    scale = min(1.20, max(manualLower, blended))
                    AppLogger.shared.log("manual_target_scale name=\(item.name) confidence=\(manualTarget.confidence) manualLongSideMM=\(String(format: "%.2f", manualTarget.manualLongSideMM)) medianMM=\(String(format: "%.2f", manualMedian)) rawManualScale=\(String(format: "%.3f", rawManualScale)) baseScale=\(String(format: "%.3f", baseScale)) blendedScale=\(String(format: "%.3f", scale)) angle=\(manualTarget.angleDegrees.map { String(format: "%.1f", $0) } ?? "nil") sourceMatch=true")
                } else {
                    AppLogger.shared.log("manual_target_skip_source_mismatch name=\(item.name) currentOriginal=\(item.originalWidth)x\(item.originalHeight) currentCropped=\(item.width)x\(item.height)")
                }
            }
            AppLogger.shared.log("item_scale name=\(item.name) class=\(shapeClass.rawValue) aspect=\(String(format: "%.3f", aspect)) fill=\(String(format: "%.3f", fillRatio)) squareFill=\(String(format: "%.3f", squareFill)) visualDelta=\(String(format: "%.3f", visualAreaDelta)) relativeScale=\(String(format: "%.3f", scale))")
            return StickerItem(
                name: item.name,
                image: item.image,
                thumbnail: item.thumbnail,
                originalWidth: item.originalWidth,
                originalHeight: item.originalHeight,
                width: item.width,
                height: item.height,
                alphaArea: item.alphaArea,
                relativeScale: scale,
                shapeClass: shapeClass
            )
        }
    }

    private func renderPreview(drawGuides: Bool) -> NSImage? {
        let width = settings.sheetWidthPX
        let height = settings.sheetHeightPX
        guard let context = CGContext(
            data: nil,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return nil }

        if settings.isTemplateMaterial {
            drawTemplateBackground(context: context, width: width, height: height)
        } else if drawGuides {
            drawCheckerboard(context: context, width: width, height: height, tile: max(24, width / 80))
        } else {
            context.clear(CGRect(x: 0, y: 0, width: width, height: height))
        }
        context.interpolationQuality = .high

        for placement in placements {
            let cell = stats?.cell ?? NestEngine.cellSize(for: settings)
            let x = (placement.gridX + placement.variant.gapCells) * cell
            let y = (placement.gridY + placement.variant.gapCells) * cell
            let rect = CGRect(
                x: x,
                y: height - y - placement.variant.height,
                width: placement.variant.width,
                height: placement.variant.height
            )
            context.draw(placement.variant.image, in: rect)
            if drawGuides {
                drawGuide(context: context, placement: placement, sheetHeight: height, cell: cell)
            }
        }

        if drawGuides {
            drawVisualAuditOverlay(context: context, width: width, height: height)
            drawEdgeSafetyOverlay(context: context, width: width, height: height)
        }

        if settings.isTemplateMaterial {
            drawTemplateOverlay(context: context, width: width, height: height)
        }

        context.setStrokeColor(CGColor(gray: 0.1, alpha: 1))
        context.setLineWidth(max(2, Double(width) / 900))
        context.stroke(CGRect(x: 0, y: 0, width: width, height: height))

        guard let cg = context.makeImage() else { return nil }
        return NSImage(cgImage: cg, size: NSSize(width: width, height: height))
    }

    private struct TemplateElement {
        let name: String
        let x: Int
        let y: Int
        let width: Int
        let height: Int
        let resourceName: String?
    }

    private var templateElements: [TemplateElement] {
        [
            TemplateElement(name: "左上角标", x: 106, y: 106, width: 224, height: 224, resourceName: nil),
            TemplateElement(name: "右上角标", x: 4630, y: 106, width: 224, height: 224, resourceName: nil),
            TemplateElement(name: "左下角标", x: 106, y: 6686, width: 224, height: 224, resourceName: nil),
            TemplateElement(name: "右下角标", x: 4630, y: 6686, width: 224, height: 224, resourceName: nil)
        ]
    }

    private var templatePSDURL: URL? {
        guard let rawPath = ProcessInfo.processInfo.environment["STICKERNEST_TEMPLATE_PSD"]?
            .trimmingCharacters(in: .whitespacesAndNewlines),
              !rawPath.isEmpty
        else { return nil }
        return URL(fileURLWithPath: rawPath)
    }

    private func templateCompositeImage() -> CGImage? {
        guard let templatePSDURL,
              FileManager.default.fileExists(atPath: templatePSDURL.path),
              let image = NSImage(contentsOf: templatePSDURL)
        else { return nil }
        return image.cgImage(forProposedRect: nil, context: nil, hints: nil)
    }

    private func drawTemplateBackground(context: CGContext, width: Int, height: Int) {
        context.setFillColor(CGColor(gray: 1, alpha: 1))
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
    }

    private func drawTemplateOverlay(context: CGContext, width: Int, height: Int) {
        let template = templateCompositeImage()
        if template == nil {
            drawGeneratedTemplateOverlay(context: context, width: width, height: height)
        }
        for element in templateElements {
            guard let crop = templateElementImage(element, template: template) else { continue }
            let drawRect = CGRect(
                x: element.x,
                y: height - element.y - element.height,
                width: element.width,
                height: element.height
            )
            context.draw(crop, in: drawRect)
        }
    }

    private func templateElementImage(_ element: TemplateElement, template: CGImage?) -> CGImage? {
        if let resourceName = element.resourceName,
           let url = Bundle.main.url(forResource: resourceName, withExtension: "png"),
           let image = NSImage(contentsOf: url),
           let cg = image.cgImage(forProposedRect: nil, context: nil, hints: nil) {
            return cg
        }
        guard let template else {
            return generatedTemplateElementImage(element)
        }
        let cropY = template.height - element.y - element.height
        let rect = CGRect(x: element.x, y: cropY, width: element.width, height: element.height)
        return template.cropping(to: rect)
    }

    private func generatedTemplateElementImage(_ element: TemplateElement) -> CGImage? {
        guard element.resourceName == nil else { return nil }
        guard let context = CGContext(
            data: nil,
            width: element.width,
            height: element.height,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return nil }
        context.clear(CGRect(x: 0, y: 0, width: element.width, height: element.height))
        context.setFillColor(CGColor(gray: 0, alpha: 1))
        let stroke = min(20, max(1, min(element.width, element.height) / 8))
        let verticalX = element.name.contains("右") ? element.width - stroke : 0
        let horizontalY = element.name.contains("下") ? 0 : element.height - stroke
        context.fill(CGRect(x: verticalX, y: 0, width: stroke, height: element.height))
        context.fill(CGRect(x: 0, y: horizontalY, width: element.width, height: stroke))
        return context.makeImage()
    }

    private func drawGeneratedTemplateOverlay(context: CGContext, width: Int, height: Int) {
        context.setFillColor(CGColor(gray: 0, alpha: 1))
        let mark = 224
        let inset = 106
        let stroke = 20
        func drawCorner(x: Int, yFromTop: Int, flipX: Bool, flipY: Bool) {
            let x0 = flipX ? x + mark - stroke : x
            let y0 = height - yFromTop - mark
            let yV = flipY ? y0 : y0
            context.fill(CGRect(x: x0, y: yV, width: stroke, height: mark))
            let xH = flipX ? x : x
            let yH = flipY ? y0 : y0 + mark - stroke
            context.fill(CGRect(x: xH, y: yH, width: mark, height: stroke))
        }
        drawCorner(x: inset, yFromTop: inset, flipX: false, flipY: false)
        drawCorner(x: width - inset - mark, yFromTop: inset, flipX: true, flipY: false)
        drawCorner(x: inset, yFromTop: height - inset - mark, flipX: false, flipY: true)
        drawCorner(x: width - inset - mark, yFromTop: height - inset - mark, flipX: true, flipY: true)
        context.stroke(CGRect(x: 2399, y: height - 6806 - 168, width: 169, height: 168))
    }

    private func drawCheckerboard(context: CGContext, width: Int, height: Int, tile: Int) {
        context.setFillColor(CGColor(red: 0.97, green: 0.98, blue: 0.95, alpha: 1))
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        for y in stride(from: 0, to: height, by: tile) {
            for x in stride(from: 0, to: width, by: tile) {
                let light = ((x / tile) + (y / tile)).isMultiple(of: 2)
                context.setFillColor(light
                    ? CGColor(red: 0.94, green: 0.95, blue: 0.91, alpha: 1)
                    : CGColor(red: 0.86, green: 0.88, blue: 0.83, alpha: 1)
                )
                context.fill(CGRect(x: x, y: y, width: tile, height: tile))
            }
        }
    }

    private func drawVisualAuditOverlay(context: CGContext, width: Int, height: Int) {
        guard let stats, !placements.isEmpty else { return }
        let result: NestEngine.NestResult = (placements, stats, [], [])
        let sparseTiles = NestEngine.visualAuditSparseTiles(for: result)
        guard !sparseTiles.isEmpty else { return }

        let rows = 10
        let columns = 8
        context.saveGState()
        for tile in sparseTiles {
            let x0 = tile.column * width / columns
            let x1 = (tile.column + 1) * width / columns
            let y0 = tile.row * height / rows
            let y1 = (tile.row + 1) * height / rows
            let severity = max(0, min(1, (0.28 - tile.fill) / 0.28))
            let rect = CGRect(
                x: x0,
                y: height - y1,
                width: max(1, x1 - x0),
                height: max(1, y1 - y0)
            )
            context.setFillColor(CGColor(red: 1.0, green: 0.26, blue: 0.08, alpha: 0.05 + 0.10 * severity))
            context.fill(rect)
            context.setStrokeColor(CGColor(red: 1.0, green: 0.18, blue: 0.02, alpha: 0.28 + 0.18 * severity))
            context.setLineWidth(max(3, Double(width) / 1500))
            context.stroke(rect.insetBy(dx: 2, dy: 2))
        }
        context.restoreGState()
    }

    private func drawEdgeSafetyOverlay(context: CGContext, width: Int, height: Int) {
        let inset = max(1, Int((NestSettings.edgeSafetyMarginMM * settings.pxPerMM).rounded()))
        guard inset * 2 < width, inset * 2 < height else { return }
        context.saveGState()
        context.setStrokeColor(CGColor(red: 0.0, green: 0.45, blue: 1.0, alpha: 0.70))
        context.setLineWidth(max(3, Double(width) / 1200))
        context.setLineDash(phase: 0, lengths: [CGFloat(max(12, width / 180)), CGFloat(max(8, width / 260))])
        context.stroke(CGRect(x: inset, y: inset, width: width - inset * 2, height: height - inset * 2))
        context.restoreGState()
    }

    private func drawGuide(context: CGContext, placement: Placement, sheetHeight: Int, cell: Int) {
        let variant = placement.variant
        context.setFillColor(CGColor(red: 0.06, green: 0.46, blue: 0.43, alpha: 0.42))
        for gy in 0..<variant.gridHeight {
            for gx in 0..<variant.gridWidth where variant.mask[gy * variant.gridWidth + gx] != 0 {
                let edge = gx == 0 || gy == 0 || gx == variant.gridWidth - 1 || gy == variant.gridHeight - 1 ||
                    variant.mask[gy * variant.gridWidth + max(0, gx - 1)] == 0 ||
                    variant.mask[gy * variant.gridWidth + min(variant.gridWidth - 1, gx + 1)] == 0 ||
                    variant.mask[max(0, gy - 1) * variant.gridWidth + gx] == 0 ||
                    variant.mask[min(variant.gridHeight - 1, gy + 1) * variant.gridWidth + gx] == 0
                if edge {
                    let x = (placement.gridX + gx) * cell
                    let topY = (placement.gridY + gy) * cell
                    context.fill(CGRect(x: x, y: sheetHeight - topY - cell, width: max(1, cell / 2), height: max(1, cell / 2)))
                }
            }
        }
    }
}

enum NestEngine {
    typealias NestResult = (placements: [Placement], stats: NestStats, unplaced: [StickerItem], debugLines: [String])

    struct LayoutOrientationStats {
        let readable: Int
        let upright: Int
        let small: Int
        let upside: Int
        let sideways: Int
        let hardOther: Int

        var hard: Int { upside + sideways + hardOther }

        var logText: String {
            "swiftOrientationStats=readable=\(readable),upright=\(upright),small=\(small),upside=\(upside),sideways=\(sideways),hard=\(hard)"
        }
    }

    private struct ExternalAutoNestOutput: Decodable {
        struct Entry: Decodable {
            struct MaskRun: Decodable {
                let y: Int
                let x0: Int
                let x1: Int
            }

            let name: String
            let x: Int
            let y: Int
            let w: Int?
            let h: Int?
            let maskX: Int?
            let maskY: Int?
            let maskW: Int?
            let maskH: Int?
            let maskDownsample: Int?
            let maskRuns: [MaskRun]?
            let angle: Int
            let scale: Double
            let layerOrder: Int?

            enum CodingKeys: String, CodingKey {
                case name
                case x
                case y
                case w
                case h
                case maskX = "mask_x"
                case maskY = "mask_y"
                case maskW = "mask_w"
                case maskH = "mask_h"
                case maskDownsample = "mask_downsample"
                case maskRuns = "mask_runs"
                case angle
                case scale
                case layerOrder = "layer_order"
            }
        }

        let paperWMM: Double?
        let paperHMM: Double?
        let dpi: Int?
        let gapMM: Double?
        let targetLongSideMM: Double?
        let gapModel: String?
        let maskDownsample: Int?
        let seed: Int?
        let alpha: Double?
        let coverageBBox: Double?
        let qualityScore: Double?
        let readabilityScore: Double?
        let orientationStats: [String: Double]?
        let angleHistogram: [String: Int]?
        let count: Int?
        let placements: [Entry]

        enum CodingKeys: String, CodingKey {
            case paperWMM = "paper_w_mm"
            case paperHMM = "paper_h_mm"
            case dpi
            case gapMM = "gap_mm"
            case targetLongSideMM = "target_long_side_mm"
            case gapModel = "gap_model"
            case maskDownsample = "mask_downsample"
            case seed
            case alpha
            case coverageBBox = "coverage_bbox"
            case qualityScore = "quality_score"
            case readabilityScore = "readability_score"
            case orientationStats = "orientation_stats"
            case angleHistogram = "angle_histogram"
            case count
            case placements
        }

        var orientationLogText: String {
            var parts: [String] = []
            if let qualityScore {
                parts.append("quality=\(String(format: "%.3f", qualityScore))")
            }
            if let readabilityScore {
                parts.append("readability=\(String(format: "%.3f", readabilityScore))")
            }
            if let stats = orientationStats {
                let keys = ["readable", "upright", "small", "upside", "sideways", "hard"]
                let counts = keys.compactMap { key -> String? in
                    guard let value = stats[key] else { return nil }
                    return "\(key)=\(Int(value.rounded()))"
                }
                if !counts.isEmpty {
                    parts.append("orientationStats=\(counts.joined(separator: ","))")
                }
                let ratioKeys = ["readable_ratio", "upside_ratio", "sideways_ratio", "hard_ratio"]
                let ratios = ratioKeys.compactMap { key -> String? in
                    guard let value = stats[key] else { return nil }
                    return "\(key)=\(String(format: "%.2f", value))"
                }
                if !ratios.isEmpty {
                    parts.append("orientationRatios=\(ratios.joined(separator: ","))")
                }
            }
            if let angleHistogram, !angleHistogram.isEmpty {
                let text = angleHistogram
                    .sorted { (Int($0.key) ?? 0) < (Int($1.key) ?? 0) }
                    .map { "\($0.key):\($0.value)" }
                    .joined(separator: ",")
                parts.append("angles=\(text)")
            }
            return parts.joined(separator: " ")
        }
    }

    static func rebuildExternalAutoNestLayout(
        data: Data,
        items: [StickerItem],
        settings: NestSettings,
        exportedNameMap: [String: String]
    ) -> (result: NestResult, scaledItems: [StickerItem], targetCoverage: Double, externalAlpha: Double?)? {
        guard let output = try? JSONDecoder().decode(ExternalAutoNestOutput.self, from: data),
              !output.placements.isEmpty
        else {
            AppLogger.shared.log("external_auto_nest_decode_failed")
            return nil
        }

        let cell = cellSize(for: settings)
        let sheetW = max(1, settings.sheetWidthPX / cell)
        let sheetH = max(1, settings.sheetHeightPX / cell)
        let gap = gapCells(for: settings, cell: cell)
        let itemByName = Dictionary(uniqueKeysWithValues: items.map { ($0.name, $0) })
        let sortedEntries = output.placements.sorted { lhs, rhs in
            (lhs.layerOrder ?? 0) < (rhs.layerOrder ?? 0)
        }

        var placements: [Placement] = []
        var usedNames = Set<String>()
        let reservedOccupied = templateReservedOccupancy(sheetW: sheetW, sheetH: sheetH)
        var occupied = reservedOccupied
        var debug = [
            "external_auto_nest_rebuild_begin jsonCount=\(output.placements.count) gapModel=\(output.gapModel ?? "legacy") alpha=\(String(format: "%.1f%%", (output.alpha ?? 0) * 100)) bbox=\(String(format: "%.1f%%", (output.coverageBBox ?? 0) * 100))"
        ]

        for entry in sortedEntries {
            let originalName = exportedNameMap[entry.name] ?? entry.name
            guard let item = itemByName[originalName] else {
                debug.append("external_auto_nest_missing_item name=\(entry.name) mapped=\(originalName)")
                continue
            }
            let resolvedScale = max(0.50, min(1.80, entry.scale))
            let scaled = StickerItem(
                name: item.name,
                image: item.image,
                thumbnail: item.thumbnail,
                originalWidth: item.originalWidth,
                originalHeight: item.originalHeight,
                width: item.width,
                height: item.height,
                alphaArea: item.alphaArea,
                relativeScale: resolvedScale,
                shapeClass: item.shapeClass
            )
            guard let variant = ImageAlpha.makeExternalAutoNestVariant(
                item: scaled,
                angle: normalizedAngle(entry.angle),
                settings: settings,
                cell: cell,
                gapCells: gap,
                contentWidth: entry.w,
                contentHeight: entry.h,
                externalMaskWidth: entry.maskW,
                externalMaskHeight: entry.maskH,
                externalMaskDownsample: entry.maskDownsample ?? output.maskDownsample,
                externalMaskRuns: entry.maskRuns?.map { (y: $0.y, x0: $0.x0, x1: $0.x1) }
            ) else {
                debug.append("external_auto_nest_variant_failed name=\(item.name) angle=\(entry.angle) scale=\(String(format: "%.3f", resolvedScale))")
                continue
            }

            let usesExternalMask = entry.maskRuns?.isEmpty == false
            let contentGridX = Int((Double(entry.x) / Double(cell)).rounded())
            let contentGridY = Int((Double(entry.y) / Double(cell)).rounded())
            let maskGridX = entry.maskX.map { Int((Double($0) / Double(cell)).rounded()) }
            let maskGridY = entry.maskY.map { Int((Double($0) / Double(cell)).rounded()) }
            let maxGridX = max(0, sheetW - variant.gridWidth)
            let maxGridY = max(0, sheetH - variant.gridHeight)
            let proposedGridX = min(max(0, maskGridX ?? (contentGridX - variant.gapCells)), maxGridX)
            let proposedGridY = min(max(0, maskGridY ?? (contentGridY - variant.gapCells)), maxGridY)
            let nudges = usesExternalMask ? [0, -1, 1] : [0, -1, 1, -2, 2, -4, 4, -6, 6, -8, 8, -12, 12, -16, 16, -24, 24, -32, 32, -48, 48]
            var resolvedGrid: (x: Int, y: Int)?
            nudgeSearch: for dy in nudges {
                for dx in nudges {
                    let nx = min(max(0, proposedGridX + dx), maxGridX)
                    let ny = min(max(0, proposedGridY + dy), maxGridY)
                    guard nx + variant.gridWidth <= sheetW,
                          ny + variant.gridHeight <= sheetH,
                          fits(occupied, sheetW: sheetW, variant: variant, x: nx, y: ny)
                    else { continue }
                    resolvedGrid = (nx, ny)
                    break nudgeSearch
                }
            }
            guard let resolvedGrid else {
                debug.append("external_auto_nest_reject_collision_or_reserved name=\(item.name) grid=\(proposedGridX),\(proposedGridY)")
                AppLogger.shared.log(debug.joined(separator: " | "))
                return nil
            }
            if resolvedGrid.x != proposedGridX || resolvedGrid.y != proposedGridY {
                debug.append("external_auto_nest_nudged name=\(item.name) from=\(proposedGridX),\(proposedGridY) to=\(resolvedGrid.x),\(resolvedGrid.y)")
            }
            stamp(&occupied, sheetW: sheetW, variant: variant, x: resolvedGrid.x, y: resolvedGrid.y)
            placements.append(Placement(item: scaled, variant: variant, gridX: resolvedGrid.x, gridY: resolvedGrid.y))
            usedNames.insert(item.name)
        }

        let unplaced = items.filter { !usedNames.contains($0.name) }
        let resultStats = stats(for: placements, sheetW: sheetW, sheetH: sheetH, cell: cell)
        let result: NestResult = (placements, resultStats, unplaced, debug)
        let scaledByName = Dictionary(uniqueKeysWithValues: placements.map { ($0.item.name, $0.item) })
        let scaledItems = items.map { scaledByName[$0.name] ?? $0 }
        let orientationLog = output.orientationLogText
        AppLogger.shared.log("external_auto_nest_rebuild_end placed=\(placements.count) unplaced=\(unplaced.count) \(coverageDiagnosticText(for: result)) jsonAlpha=\(String(format: "%.1f%%", (output.alpha ?? 0) * 100))\(orientationLog.isEmpty ? "" : " \(orientationLog)")")
        return (result, scaledItems, sheetCoverage(result), output.alpha)
    }

